182	    fn io_error_converts_from_std() {
183	        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
184	        let err: BivvyError = io_err.into();
185	        assert!(matches!(err, BivvyError::Io(_)));
