188	    #[test]
189	    fn result_type_alias_works() {
190	        fn returns_error() -> Result<()> {
191	            Err(BivvyError::ConfigValidationError {
192	                message: "test".into(),
193	            })
194	        }
195	        assert!(returns_error().is_err());
196	    }
197	}
