1	//! Detector registry for shared, cacheable detection checks.
2	//!
3	//! Detectors are named, structured check definitions with addressable facets.
4	//! They are defined once in `templates/detectors.yml` and referenced by
5	//! templates via dot notation (e.g., `rails-project.files.application` or
6	//! `gemfile-present.file`).
7	//!
8	//! # Reference Syntax
9	//!
10	//! - `rails-project` — bare name: ANY check across all groups passes (OR)
11	//! - `rails-project.commands` — run all commands (OR semantics)
12	//! - `rails-project.files` — check all files (OR semantics)
13	//! - `rails-project.commands.rails_version` — run a specific named command
14	//! - `rails-project.files.application` — check a specific named file
15	//! - `gemfile-present.command` — singular command shorthand
16	//! - `gemfile-present.file` — singular file shorthand
17	//!
18	//! # Evaluation Semantics
19	//!
20	//! - **commands group** (plural): ANY must succeed (OR)
21	//! - **files group** (plural): ANY must exist (OR)
22	//! - **single command**: must succeed
23	//! - **single file**: must exist
24	//! - **bare detector name**: ANY check across all groups passes (OR)
25	
26	use serde::{Deserialize, Serialize};
27	use std::cell::RefCell;
28	use std::collections::HashMap;
29	use std::path::Path;
30	
31	use crate::detection::command_detection::command_succeeds;
32	use crate::detection::file_detection::file_exists;
33	use crate::error::{BivvyError, Result};
