35	/// Top-level detectors file structure.
36	///
37	/// Corresponds to the `templates/detectors.yml` file format.
38	#[derive(Debug, Clone, Deserialize, Serialize)]
39	pub struct DetectorFile {
40	    /// Map of detector name to definition.
41	    pub detectors: HashMap<String, DetectorDef>,
42	}
43	
44	/// A single detector definition.
45	///
46	/// Supports both singular (`command`/`file`) and plural (`commands`/`files`)
47	/// forms. Singular values are merged into the plural maps with the key
48	/// `"default"` when accessed via [`all_commands`](DetectorDef::all_commands)
49	/// or [`all_files`](DetectorDef::all_files).
50	#[derive(Debug, Clone, Deserialize, Serialize)]
51	pub struct DetectorDef {
52	    /// Singular command shorthand.
53	    #[serde(default)]
54	    pub command: Option<String>,
55	
56	    /// Named commands map.
57	    #[serde(default)]
58	    pub commands: HashMap<String, String>,
59	
60	    /// Singular file shorthand.
61	    #[serde(default)]
62	    pub file: Option<String>,
63	
64	    /// Named files map.
65	    #[serde(default)]
66	    pub files: HashMap<String, String>,
67	}
68	
69	impl DetectorDef {
70	    /// Get all commands, merging the singular `command` field into the map
71	    /// with key `"default"` if not already present.
72	    pub fn all_commands(&self) -> HashMap<String, String> {
73	        let mut cmds = self.commands.clone();
74	        if let Some(ref cmd) = self.command {
75	            cmds.entry("default".to_string())
76	                .or_insert_with(|| cmd.clone());
77	        }
78	        cmds
79	    }
80	
81	    /// Get all files, merging the singular `file` field into the map
82	    /// with key `"default"` if not already present.
83	    pub fn all_files(&self) -> HashMap<String, String> {
84	        let mut files = self.files.clone();
85	        if let Some(ref f) = self.file {
86	            files
87	                .entry("default".to_string())
88	                .or_insert_with(|| f.clone());
89	        }
90	        files
91	    }
92	
93	    /// Check if this detector has any checks defined.
94	    pub fn has_checks(&self) -> bool {
95	        self.command.is_some()
96	            || !self.commands.is_empty()
97	            || self.file.is_some()
98	            || !self.files.is_empty()
99	    }
100	}
