102	/// Parsed reference to a detector facet.
103	///
104	/// Created by [`DetectorRef::parse`] from a dot-notation string.
105	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
106	pub struct DetectorRef {
107	    /// The detector name (first segment).
108	    pub detector: String,
109	    /// The group being referenced (second segment).
110	    pub group: Option<DetectorGroup>,
111	    /// A specific named entry within the group (third segment).
112	    pub specific: Option<String>,
113	}
114	
115	/// Which group of checks a detector reference targets.
116	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
117	pub enum DetectorGroup {
118	    /// Plural commands group (OR semantics).
119	    Commands,
120	    /// Plural files group (OR semantics).
121	    Files,
122	    /// Singular command shorthand.
123	    Command,
124	    /// Singular file shorthand.
125	    File,
126	}
127	
128	impl DetectorRef {
129	    /// Parse a detector reference string like `"rails.commands.rails_version"`.
130	    ///
131	    /// # Errors
132	    ///
133	    /// Returns an error if the group segment is unrecognized or if a specific
134	    /// name is used with a singular group (`command` or `file`).
135	    pub fn parse(s: &str) -> Result<Self> {
136	        let parts: Vec<&str> = s.splitn(3, '.').collect();
137	        match parts.len() {
138	            1 => Ok(DetectorRef {
139	                detector: parts[0].to_string(),
140	                group: None,
141	                specific: None,
142	            }),
143	            2 => {
144	                let group = match parts[1] {
145	                    "commands" => DetectorGroup::Commands,
146	                    "files" => DetectorGroup::Files,
147	                    "command" => DetectorGroup::Command,
148	                    "file" => DetectorGroup::File,
149	                    other => {
150	                        return Err(BivvyError::ConfigValidationError {
151	                            message: format!(
152	                                "Invalid detector group '{}' in '{}'. Expected: commands, files, command, file",
153	                                other, s
154	                            ),
155	                        })
156	                    }
157	                };
158	                Ok(DetectorRef {
159	                    detector: parts[0].to_string(),
160	                    group: Some(group),
161	                    specific: None,
162	                })
163	            }
164	            3 => {
165	                let group = match parts[1] {
166	                    "commands" => DetectorGroup::Commands,
167	                    "files" => DetectorGroup::Files,
168	                    other => {
169	                        return Err(BivvyError::ConfigValidationError {
170	                            message: format!(
171	                                "Invalid detector group '{}' in '{}'. Specific references require 'commands' or 'files'",
172	                                other, s
173	                            ),
174	                        })
175	                    }
176	                };
177	                Ok(DetectorRef {
178	                    detector: parts[0].to_string(),
179	                    group: Some(group),
180	                    specific: Some(parts[2].to_string()),
181	                })
182	            }
183	            _ => Err(BivvyError::ConfigValidationError {
184	                message: format!("Invalid detector reference: '{}'", s),
185	            }),
186	        }
187	    }
188	}
