190	/// Result of evaluating a detector reference.
191	#[derive(Debug, Clone)]
192	pub struct DetectorResult {
193	    /// Whether the detector check passed.
194	    pub passed: bool,
195	    /// The original reference string.
196	    pub reference: String,
197	    /// Human-readable detail lines describing each sub-check.
198	    pub details: Vec<String>,
199	}
200	
201	/// Registry that holds detector definitions and evaluates references with caching.
202	///
203	/// Results are cached within a session to avoid redundant command executions
204	/// and file-system checks.
205	pub struct DetectorRegistry {
206	    detectors: HashMap<String, DetectorDef>,
207	    cache: RefCell<HashMap<String, bool>>,
208	}
209	
210	impl DetectorRegistry {
211	    /// Create a new registry from a parsed detector file.
212	    pub fn new(file: DetectorFile) -> Self {
213	        Self {
214	            detectors: file.detectors,
215	            cache: RefCell::new(HashMap::new()),
216	        }
217	    }
218	
219	    /// Get a detector definition by name.
220	    pub fn get(&self, name: &str) -> Option<&DetectorDef> {
221	        self.detectors.get(name)
222	    }
223	
224	    /// List all detector names.
225	    pub fn names(&self) -> Vec<&String> {
226	        self.detectors.keys().collect()
227	    }
228	
229	    /// Clear the evaluation cache.
230	    pub fn clear_cache(&self) {
231	        self.cache.borrow_mut().clear();
232	    }
233	
234	    /// Evaluate a single detector reference.
235	    ///
236	    /// # Errors
237	    ///
238	    /// Returns an error if the reference is malformed or references an
239	    /// unknown detector or facet.
240	    pub fn evaluate(&self, reference: &str, project_root: &Path) -> Result<DetectorResult> {
241	        let parsed = DetectorRef::parse(reference)?;
242	
243	        let def = self.detectors.get(&parsed.detector).ok_or_else(|| {
244	            BivvyError::ConfigValidationError {
245	                message: format!("Unknown detector: '{}'", parsed.detector),
246	            }
247	        })?;
248	
249	        let (passed, details) = match (&parsed.group, &parsed.specific) {
250	            // Bare name: ANY check across all groups passes (OR)
251	            (None, None) => {
252	                let (cmds_pass, mut details) = self.eval_commands_group(def);
253	                let (files_pass, file_details) = self.eval_files_group(def, project_root);
254	                details.extend(file_details);
255	                (cmds_pass || files_pass, details)
256	            }
257	
258	            // commands group (any must pass)
259	            (Some(DetectorGroup::Commands), None) => self.eval_commands_group(def),
260	
261	            // files group (any must exist)
262	            (Some(DetectorGroup::Files), None) => self.eval_files_group(def, project_root),
263	
264	            // command singular shorthand
265	            (Some(DetectorGroup::Command), None) => {
266	                self.eval_command_singular(def, &parsed.detector)?
267	            }
268	
269	            // file singular shorthand
270	            (Some(DetectorGroup::File), None) => {
271	                self.eval_file_singular(def, &parsed.detector, project_root)?
272	            }
273	
274	            // specific command
275	            (Some(DetectorGroup::Commands), Some(name)) => {
276	                self.eval_specific_command(def, &parsed.detector, name)?
277	            }
278	
279	            // specific file
280	            (Some(DetectorGroup::Files), Some(name)) => {
281	                self.eval_specific_file(def, &parsed.detector, name, project_root)?
282	            }
283	
284	            // singular shorthands can't have specifics
285	            (Some(DetectorGroup::Command), Some(_)) | (Some(DetectorGroup::File), Some(_)) => {
286	                return Err(BivvyError::ConfigValidationError {
287	                    message: format!(
288	                        "Cannot use specific name with singular 'command' or 'file' in '{}'",
289	                        reference
290	                    ),
291	                });
292	            }
293	
294	            // bare name with specific but no group -- unreachable via parse but needed for exhaustiveness
295	            (None, Some(_)) => {
296	                return Err(BivvyError::ConfigValidationError {
297	                    message: format!("Invalid detector reference: '{}'", reference),
298	                });
299	            }
300	        };
301	
302	        Ok(DetectorResult {
303	            passed,
304	            reference: reference.to_string(),
305	            details,
306	        })
307	    }
308	
309	    /// Evaluate multiple detector references. Returns true if ALL pass.
310	    pub fn evaluate_all(&self, references: &[String], project_root: &Path) -> Result<bool> {
311	        for reference in references {
312	            let result = self.evaluate(reference, project_root)?;
313	            if !result.passed {
314	                return Ok(false);
315	            }
316	        }
317	        Ok(true)
318	    }
319	
320	    // --- Private evaluation helpers ---
321	
322	    fn eval_commands_group(&self, def: &DetectorDef) -> (bool, Vec<String>) {
323	        let cmds = def.all_commands();
324	        if cmds.is_empty() {
325	            return (true, Vec::new());
326	        }
327	        let mut details = Vec::new();
328	        let mut any_pass = false;
329	        for (name, cmd) in &cmds {
330	            let pass = self.eval_command_cached(cmd);
331	            if pass {
332	                any_pass = true;
333	            }
334	            details.push(format!(
335	                "{}: {} ({})",
336	                name,
337	                if pass { "passed" } else { "failed" },
338	                cmd
339	            ));
340	        }
341	        (any_pass, details)
342	    }
343	
344	    fn eval_files_group(&self, def: &DetectorDef, project_root: &Path) -> (bool, Vec<String>) {
345	        let files = def.all_files();
346	        if files.is_empty() {
347	            return (true, Vec::new());
348	        }
349	        let mut details = Vec::new();
350	        let mut any_pass = false;
351	        for (name, path) in &files {
352	            let pass = self.eval_file_cached(project_root, path);
353	            if pass {
354	                any_pass = true;
355	            }
356	            details.push(format!(
357	                "{}: {} ({})",
358	                name,
359	                if pass { "found" } else { "missing" },
360	                path
361	            ));
362	        }
363	        (any_pass, details)
364	    }
365	
366	    fn eval_command_singular(
367	        &self,
368	        def: &DetectorDef,
369	        detector_name: &str,
370	    ) -> Result<(bool, Vec<String>)> {
371	        let cmd = def
372	            .command
373	            .as_ref()
374	            .or_else(|| def.commands.values().next())
375	            .ok_or_else(|| BivvyError::ConfigValidationError {
376	                message: format!("Detector '{}' has no command defined", detector_name),
377	            })?;
378	        let pass = self.eval_command_cached(cmd);
379	        Ok((
380	            pass,
381	            vec![format!(
382	                "{} ({})",
383	                if pass { "passed" } else { "failed" },
384	                cmd
385	            )],
386	        ))
387	    }
388	
389	    fn eval_file_singular(
390	        &self,
391	        def: &DetectorDef,
392	        detector_name: &str,
393	        project_root: &Path,
394	    ) -> Result<(bool, Vec<String>)> {
395	        let f = def
396	            .file
397	            .as_ref()
398	            .or_else(|| def.files.values().next())
399	            .ok_or_else(|| BivvyError::ConfigValidationError {
400	                message: format!("Detector '{}' has no file defined", detector_name),
401	            })?;
402	        let pass = self.eval_file_cached(project_root, f);
403	        Ok((
404	            pass,
405	            vec![format!(
406	                "{} ({})",
407	                if pass { "found" } else { "missing" },
408	                f
409	            )],
410	        ))
411	    }
412	
413	    fn eval_specific_command(
414	        &self,
415	        def: &DetectorDef,
416	        detector_name: &str,
417	        name: &str,
418	    ) -> Result<(bool, Vec<String>)> {
419	        let cmd = def.all_commands().get(name).cloned().ok_or_else(|| {
420	            BivvyError::ConfigValidationError {
421	                message: format!(
422	                    "Detector '{}' has no command named '{}'",
423	                    detector_name, name
424	                ),
425	            }
426	        })?;
427	        let pass = self.eval_command_cached(&cmd);
428	        Ok((
429	            pass,
430	            vec![format!(
431	                "{}: {} ({})",
432	                name,
433	                if pass { "passed" } else { "failed" },
434	                cmd
435	            )],
436	        ))
437	    }
438	
439	    fn eval_specific_file(
440	        &self,
441	        def: &DetectorDef,
442	        detector_name: &str,
443	        name: &str,
444	        project_root: &Path,
445	    ) -> Result<(bool, Vec<String>)> {
446	        let f = def.all_files().get(name).cloned().ok_or_else(|| {
447	            BivvyError::ConfigValidationError {
448	                message: format!("Detector '{}' has no file named '{}'", detector_name, name),
449	            }
450	        })?;
451	        let pass = self.eval_file_cached(project_root, &f);
452	        Ok((
453	            pass,
454	            vec![format!(
455	                "{}: {} ({})",
456	                name,
457	                if pass { "found" } else { "missing" },
458	                f
459	            )],
460	        ))
461	    }
462	
463	    fn eval_command_cached(&self, cmd: &str) -> bool {
464	        let key = format!("cmd:{}", cmd);
465	        if let Some(&cached) = self.cache.borrow().get(&key) {
466	            return cached;
467	        }
468	        let result = command_succeeds(cmd);
469	        self.cache.borrow_mut().insert(key, result);
470	        result
471	    }
472	
473	    fn eval_file_cached(&self, project_root: &Path, path: &str) -> bool {
474	        let key = format!("file:{}:{}", project_root.display(), path);
475	        if let Some(&cached) = self.cache.borrow().get(&key) {
476	            return cached;
477	        }
478	        let result = file_exists(project_root, path);
479	        self.cache.borrow_mut().insert(key, result);
480	        result
481	    }
482	}
