13	/// Load the built-in registry manifest.
14	pub fn load_manifest() -> Result<RegistryManifest> {
15	    let manifest_file = TEMPLATES_DIR.get_file("registry.yml").ok_or_else(|| {
16	        crate::error::BivvyError::ConfigNotFound {
17	            path: "templates/registry.yml".into(),
18	        }
19	    })?;
20	
21	    let content = manifest_file.contents_utf8().ok_or_else(|| {
22	        crate::error::BivvyError::ConfigParseError {
23	            path: "templates/registry.yml".into(),
24	            message: "Invalid UTF-8".to_string(),
25	        }
26	    })?;
27	
28	    serde_yaml::from_str(content).map_err(|e| crate::error::BivvyError::ConfigParseError {
29	        path: "templates/registry.yml".into(),
30	        message: e.to_string(),
31	    })
32	}
