34	/// Load the built-in detector definitions.
35	pub fn load_detectors() -> Result<DetectorFile> {
36	    let detector_file = TEMPLATES_DIR.get_file("detectors.yml").ok_or_else(|| {
37	        crate::error::BivvyError::ConfigNotFound {
38	            path: "templates/detectors.yml".into(),
39	        }
40	    })?;
