44	            path: "templates/detectors.yml".into(),
45	            message: "Invalid UTF-8".to_string(),
46	        }
47	    })?;
48	
49	    serde_yaml::from_str(content).map_err(|e| crate::error::BivvyError::ConfigParseError {
