55	/// Build a qualified key for a template (`category/name`).
56	fn qualified_key(template: &Template) -> String {
57	    format!("{}/{}", template.category, template.name)
58	}
59	
60	/// Load all built-in templates, keyed by `category/name`.
61	pub fn load_templates() -> Result<HashMap<String, Template>> {
62	    let mut templates = HashMap::new();
63	    load_templates_from_dir(&TEMPLATES_DIR, "steps", &mut templates)?;
64	    Ok(templates)
65	}
66	
67	fn load_templates_from_dir(
68	    dir: &Dir<'_>,
69	    prefix: &str,
70	    templates: &mut HashMap<String, Template>,
71	) -> Result<()> {
72	    let steps_dir = dir.get_dir(prefix);
73	
74	    if let Some(steps) = steps_dir {
75	        for entry in steps.dirs() {
76	            // Each subdirectory is a category (ruby, node, common, etc.)
77	            for file in entry.files() {
78	                if let Some(ext) = file.path().extension() {
79	                    if ext == "yml" || ext == "yaml" {
80	                        if let Some(content) = file.contents_utf8() {
81	                            let template: Template =
82	                                serde_yaml::from_str(content).map_err(|e| {
83	                                    crate::error::BivvyError::ConfigParseError {
84	                                        path: file.path().to_path_buf(),
85	                                        message: e.to_string(),
86	                                    }
87	                                })?;
88	                            let key = qualified_key(&template);
89	                            templates.insert(key, template);
90	                        }
91	                    }
92	                }
93	            }
94	        }
95	    }
96	
97	    Ok(())
98	}
99	
100	/// Check if a template exists in built-ins.
101	pub fn has_template(name: &str) -> bool {
102	    load_templates()
103	        .map(|t| {
104	            // Check qualified key first, then unqualified name
105	            t.contains_key(name) || t.values().any(|tmpl| tmpl.name == name)
106	        })
107	        .unwrap_or(false)
108	}
