110	/// Loader for built-in templates.
111	#[derive(Debug, Clone)]
112	pub struct BuiltinLoader {
113	    templates: HashMap<String, Template>,
114	    manifest: RegistryManifest,
115	}
116	
117	impl BuiltinLoader {
118	    /// Initialize the built-in loader.
119	    pub fn new() -> Result<Self> {
120	        Ok(Self {
121	            templates: load_templates()?,
122	            manifest: load_manifest()?,
123	        })
124	    }
125	
126	    /// Get a template by name (unqualified — returns first match).
127	    pub fn get(&self, name: &str) -> Option<&Template> {
128	        // Try as qualified key first
129	        if let Some(t) = self.templates.get(name) {
130	            return Some(t);
131	        }
132	        // Fall back to unqualified name match
133	        self.templates.values().find(|t| t.name == name)
134	    }
135	
136	    /// Get a template by name, filtering by category.
137	    pub fn get_by_category(&self, name: &str, category: &str) -> Option<&Template> {
138	        let key = format!("{}/{}", category, name);
139	        self.templates.get(&key)
140	    }
141	
142	    /// Get all template names (qualified as `category/name`).
143	    pub fn template_names(&self) -> Vec<&str> {
144	        self.templates.keys().map(|s| s.as_str()).collect()
145	    }
146	
147	    /// Get templates filtered by current platform.
148	    pub fn templates_for_current_platform(&self) -> Vec<&Template> {
149	        self.templates
150	            .values()
151	            .filter(|t| t.platforms.iter().any(|p| p.is_current()))
152	            .collect()
153	    }
154	
155	    /// Get templates in detection order for current platform.
156	    pub fn detection_order(&self) -> Vec<&Template> {
157	        self.manifest
158	            .detection_order
159	            .iter()
160	            .filter_map(|name| self.get(name))
161	            .filter(|t| t.platforms.iter().any(|p| p.is_current()))
162	            .collect()
163	    }
164	
165	    /// Get the manifest.
166	    pub fn manifest(&self) -> &RegistryManifest {
167	        &self.manifest
168	    }
169	
170	    /// Get source type for built-in templates.
171	    pub fn source() -> TemplateSource {
172	        TemplateSource::Builtin
173	    }
174	}
175	
176	impl Default for BuiltinLoader {
177	    fn default() -> Self {
178	        Self::new().expect("Built-in templates should always load")
179	    }
180	}
