589	        let server = MockServer::start();
590	
591	        server.mock(|when, then| {
592	            when.method(GET).path("/concurrent.yml");
593	            then.status(200).body("concurrent: true\ndata: value\n");
594	        });
595	
596	        let temp = TempDir::new().unwrap();
597	        let cache_dir = temp.path().join("cache");
598	        let url = server.url("/concurrent.yml");
599	
600	        // Create multiple threads that all fetch the same URL
601	        let handles: Vec<_> = (0..4)
602	            .map(|_| {
603	                let url = url.clone();
604	                let cache_dir = cache_dir.clone();
605	                std::thread::spawn(move || {
606	                    let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
607	                    fetcher.fetch(&url).unwrap()
608	                })
609	            })
610	            .collect();
611	
612	        let results: Vec<String> = handles.into_iter().map(|h| h.join().unwrap()).collect();
613	
614	        // All threads should get the correct content
615	        for result in &results {
616	            assert_eq!(result, "concurrent: true\ndata: value\n");
617	        }
618	    }
