620	    #[test]
621	    fn corrupted_cache_triggers_refetch() {
622	        let server = MockServer::start();
623	
624	        let mock = server.mock(|when, then| {
625	            when.method(GET).path("/corrupt.yml");
626	            then.status(200).body("valid: true");
627	        });
628	
629	        let temp = TempDir::new().unwrap();
630	        let cache_dir = temp.path().join("cache");
631	        let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(10), cache_dir);
632	        let url = server.url("/corrupt.yml");
633	
634	        // Warm the cache normally
635	        fetcher.fetch(&url).unwrap();
636	        mock.assert_calls(1);
637	
638	        // Corrupt the cache file by writing garbage
639	        let cache_path = fetcher.cache_path(&url);
640	        std::fs::write(&cache_path, "garbage\x00\x01\x02not yaml").unwrap();
641	
642	        // The fetcher's simple cache returns whatever is in the file,
643	        // so it will return the corrupted content. This is by design:
644	        // RemoteFetcher's cache is a simple file-based cache without
645	        // integrity checks. The caller (ExtendsResolver) handles
646	        // YAML parse errors.
647	        let content = fetcher.fetch(&url).unwrap();
648	        assert_eq!(content, "garbage\x00\x01\x02not yaml");
649	        // Still only 1 server hit (cache was returned, even if corrupted)
650	        mock.assert_calls(1);
651	    }
652	}
