119	/// Write the auto_update setting to the system config at `~/.bivvy/config.yml`.
120	///
121	/// Only requires `OutputWriter` — displays confirmation messages but does not prompt.
122	fn set_auto_update(ui: &mut dyn OutputWriter, enabled: bool) -> Result<CommandResult> {
123	    let home = crate::sys::home_dir().ok_or_else(|| {
124	        crate::error::BivvyError::Other(anyhow::anyhow!("Could not determine home directory"))
125	    })?;
126	
127	    let config_dir = home.join(".bivvy");
128	    let config_path = config_dir.join("config.yml");
129	
130	    // Read existing config or start fresh
131	    let mut value: serde_yaml::Value = if config_path.exists() {
132	        let content = std::fs::read_to_string(&config_path).map_err(|e| {
133	            crate::error::BivvyError::Other(anyhow::anyhow!(
134	                "Failed to read {}: {}",
135	                config_path.display(),
136	                e
137	            ))
138	        })?;
139	        serde_yaml::from_str(&content)
140	            .unwrap_or(serde_yaml::Value::Mapping(serde_yaml::Mapping::new()))
141	    } else {
142	        serde_yaml::Value::Mapping(serde_yaml::Mapping::new())
143	    };
144	
145	    // Ensure settings mapping exists
146	    let mapping = value.as_mapping_mut().ok_or_else(|| {
147	        crate::error::BivvyError::Other(anyhow::anyhow!("System config is not a YAML mapping"))
148	    })?;
149	
150	    let settings_key = serde_yaml::Value::String("settings".to_string());
151	    if !mapping.contains_key(&settings_key) {
152	        mapping.insert(
153	            settings_key.clone(),
154	            serde_yaml::Value::Mapping(serde_yaml::Mapping::new()),
155	        );
156	    }
157	
158	    let settings = mapping
159	        .get_mut(&settings_key)
160	        .and_then(|v| v.as_mapping_mut())
161	        .ok_or_else(|| {
162	            crate::error::BivvyError::Other(anyhow::anyhow!("settings is not a YAML mapping"))
163	        })?;
164	
165	    settings.insert(
166	        serde_yaml::Value::String("auto_update".to_string()),
167	        serde_yaml::Value::Bool(enabled),
168	    );
169	
170	    // Write back
171	    std::fs::create_dir_all(&config_dir)?;
172	    let yaml = serde_yaml::to_string(&value).map_err(|e| {
173	        crate::error::BivvyError::Other(anyhow::anyhow!("Failed to serialize config: {}", e))
174	    })?;
175	    std::fs::write(&config_path, yaml)?;
176	
177	    if enabled {
178	        ui.message("Automatic background updates enabled.");
179	    } else {
180	        ui.message("Automatic background updates disabled.");
181	    }
182	    ui.message(&format!("Saved to {}", config_path.display()));
183	
184	    Ok(CommandResult::success())
185	}
