            fs::remove_file(&content_path).map_err(|e| BivvyError::CacheError {
                message: format!("Failed to remove cache file {:?}: {}", content_path, e),
            })?;
            removed = true;
        }

        if meta_path.exists() {
            fs::remove_file(&meta_path).map_err(|e| BivvyError::CacheError {
                message: format!("Failed to remove cache metadata {:?}: {}", meta_path, e),
            })?;
            removed = true;
        }

        Ok(removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root).map_err(|e| BivvyError::CacheError {
            message: format!("Failed to read cache directory {:?}: {}", self.root, e),
        })? {
            let entry = entry.map_err(|e| BivvyError::CacheError {
                message: format!("Failed to read cache directory entry: {}", e),
            })?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by_key(|e| std::cmp::Reverse(e.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

