1	//! Feedback storage (JSONL format).
2	
3	use std::fs::{self, File, OpenOptions};
4	use std::io::{BufRead, BufReader, Write};
5	use std::path::PathBuf;
6	
7	use crate::error::BivvyError;
8	type Result<T> = crate::error::Result<T>;
9	
10	use super::{FeedbackEntry, FeedbackStatus};
11	use crate::session::SessionId;
12	
13	/// Storage for feedback entries.
14	pub struct FeedbackStore {
15	    path: PathBuf,
16	}
17	
18	impl FeedbackStore {
19	    /// Create a new feedback store.
20	    pub fn new(path: impl Into<PathBuf>) -> Self {
21	        Self { path: path.into() }
22	    }
23	
24	    /// Get the store path.
25	    pub fn path(&self) -> &PathBuf {
26	        &self.path
27	    }
28	
29	    /// Ensure the parent directory exists.
30	    fn ensure_dir(&self) -> Result<()> {
31	        if let Some(parent) = self.path.parent() {
32	            fs::create_dir_all(parent).map_err(|e| BivvyError::FeedbackError {
33	                message: format!("Failed to create directory {:?}: {}", parent, e),
34	            })?;
35	        }
36	        Ok(())
37	    }
38	
39	    /// Append a feedback entry.
40	    pub fn append(&self, entry: &FeedbackEntry) -> Result<()> {
41	        self.ensure_dir()?;
42	
43	        let mut file = OpenOptions::new()
44	            .create(true)
45	            .append(true)
46	            .open(&self.path)
47	            .map_err(|e| BivvyError::FeedbackError {
48	                message: format!("Failed to open {:?}: {}", self.path, e),
49	            })?;
50	
51	        let json = serde_json::to_string(entry).map_err(|e| BivvyError::FeedbackError {
52	            message: format!("Failed to serialize feedback entry: {}", e),
53	        })?;
54	        writeln!(file, "{}", json).map_err(|e| BivvyError::FeedbackError {
55	            message: format!("Failed to write feedback entry: {}", e),
56	        })?;
57	
58	        Ok(())
59	    }
60	
61	    /// List all feedback entries.
62	    pub fn list_all(&self) -> Result<Vec<FeedbackEntry>> {
63	        self.read_entries(|_| true)
64	    }
65	
66	    /// List feedback by status.
67	    pub fn list_by_status(&self, status: FeedbackStatus) -> Result<Vec<FeedbackEntry>> {
68	        self.read_entries(|e| e.status == status)
69	    }
70	
71	    /// List feedback by tag.
72	    pub fn list_by_tag(&self, tag: &str) -> Result<Vec<FeedbackEntry>> {
73	        self.read_entries(|e| e.tags.iter().any(|t| t == tag))
74	    }
75	
76	    /// List feedback by session.
77	    pub fn list_by_session(&self, session_id: &SessionId) -> Result<Vec<FeedbackEntry>> {
78	        self.read_entries(|e| e.session_id.as_ref() == Some(session_id))
79	    }
80	
81	    /// Update an entry by ID.
82	    pub fn update(&self, id: &str, updater: impl FnOnce(&mut FeedbackEntry)) -> Result<bool> {
83	        let mut entries = self.list_all()?;
84	        let mut found = false;
85	
86	        for entry in &mut entries {
87	            if entry.id == id {
88	                updater(entry);
89	                found = true;
90	                break;
91	            }
92	        }
93	
94	        if found {
95	            self.rewrite_all(&entries)?;
96	        }
97	
98	        Ok(found)
99	    }
100	
101	    /// Get an entry by ID.
102	    pub fn get(&self, id: &str) -> Result<Option<FeedbackEntry>> {
103	        let entries = self.read_entries(|e| e.id == id)?;
104	        Ok(entries.into_iter().next())
105	    }
