107	    /// Read entries matching a predicate.
108	    fn read_entries(
109	        &self,
110	        predicate: impl Fn(&FeedbackEntry) -> bool,
111	    ) -> Result<Vec<FeedbackEntry>> {
112	        if !self.path.exists() {
113	            return Ok(Vec::new());
114	        }
115	
116	        let file = File::open(&self.path).map_err(|e| BivvyError::FeedbackError {
117	            message: format!("Failed to open {:?}: {}", self.path, e),
118	        })?;
119	        let reader = BufReader::new(file);
120	        let mut entries = Vec::new();
121	
122	        for line in reader.lines() {
123	            let line = line.map_err(|e| BivvyError::FeedbackError {
124	                message: format!("Failed to read feedback file: {}", e),
125	            })?;
126	            if line.trim().is_empty() {
127	                continue;
128	            }
129	            if let Ok(entry) = serde_json::from_str::<FeedbackEntry>(&line) {
130	                if predicate(&entry) {
131	                    entries.push(entry);
132	                }
133	            }
134	        }
135	
136	        Ok(entries)
137	    }
138	
139	    /// Rewrite all entries (for updates).
140	    fn rewrite_all(&self, entries: &[FeedbackEntry]) -> Result<()> {
141	        self.ensure_dir()?;
142	
143	        let mut file = File::create(&self.path)?;
144	        for entry in entries {
145	            let json = serde_json::to_string(entry)?;
146	            writeln!(file, "{}", json)?;
147	        }
148	
149	        Ok(())
150	    }
151	}
