29	    /// Ensure the parent directory exists.
30	    fn ensure_dir(&self) -> Result<()> {
31	        if let Some(parent) = self.path.parent() {
32	            fs::create_dir_all(parent).map_err(|e| BivvyError::FeedbackError {
33	                message: format!("Failed to create directory {:?}: {}", parent, e),
34	            })?;
35	        }
