39	    /// Append a feedback entry.
40	    pub fn append(&self, entry: &FeedbackEntry) -> Result<()> {
41	        self.ensure_dir()?;
42	
43	        let mut file = OpenOptions::new()
44	            .create(true)
45	            .append(true)
46	            .open(&self.path)
47	            .map_err(|e| BivvyError::FeedbackError {
