1	//! Session storage.
2	
3	use std::fs;
4	use std::path::PathBuf;
5	
6	use crate::error::BivvyError;
7	type Result<T> = crate::error::Result<T>;
8	
9	use super::{SessionId, SessionMetadata};
10	
11	/// A complete session record.
12	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
13	pub struct Session {
14	    /// Unique session identifier.
15	    pub id: SessionId,
16	    /// Session metadata.
17	    pub metadata: SessionMetadata,
18	}
19	
20	/// Storage for sessions.
21	pub struct SessionStore {
22	    path: PathBuf,
23	}
24	
25	impl SessionStore {
26	    /// Create a new session store.
27	    pub fn new(path: impl Into<PathBuf>) -> Self {
28	        Self { path: path.into() }
29	    }
30	
31	    /// Ensure the store directory exists.
32	    fn ensure_dir(&self) -> Result<()> {
33	        fs::create_dir_all(&self.path).map_err(|e| BivvyError::SessionError {
34	            message: format!("Failed to create session store at {:?}: {}", self.path, e),
35	        })
36	    }
37	
38	    /// Get the path for a session file.
39	    fn session_path(&self, id: &SessionId) -> PathBuf {
40	        self.path.join(format!("{}.json", id))
41	    }
42	
43	    /// Save a session.
44	    pub fn save(&self, session: &Session) -> Result<()> {
45	        self.ensure_dir()?;
46	        let path = self.session_path(&session.id);
47	        let json = serde_json::to_string_pretty(session).map_err(|e| BivvyError::SessionError {
48	            message: format!("Failed to serialize session: {}", e),
49	        })?;
50	        fs::write(&path, json).map_err(|e| BivvyError::SessionError {
51	            message: format!("Failed to write session to {:?}: {}", path, e),
52	        })
53	    }
54	
55	    /// Load a session by ID.
56	    pub fn load(&self, id: &SessionId) -> Result<Session> {
57	        let path = self.session_path(id);
58	        let json =
59	            fs::read_to_string(&path).map_err(|e| BivvyError::SessionError {
60	                message: format!("Session not found: {:?}: {}", path, e),
61	            })?;
62	        serde_json::from_str(&json).map_err(|e| BivvyError::SessionError {
63	            message: format!("Failed to parse session: {}", e),
64	        })
65	    }
66	
67	    /// Get the most recent session.
68	    pub fn get_latest(&self) -> Result<Option<Session>> {
69	        let sessions = self.list_recent(1)?;
70	        Ok(sessions.into_iter().next())
71	    }
72	
73	    /// List recent sessions.
74	    pub fn list_recent(&self, limit: usize) -> Result<Vec<Session>> {
75	        self.ensure_dir()?;
76	
77	        let mut sessions = Vec::new();
78	        for entry in fs::read_dir(&self.path).map_err(|e| BivvyError::SessionError {
79	            message: format!("Failed to read session directory {:?}: {}", self.path, e),
80	        })? {
81	            let entry = entry.map_err(|e| BivvyError::SessionError {
82	                message: format!("Failed to read session directory entry: {}", e),
83	            })?;
84	            let path = entry.path();
85	            if path.extension().is_some_and(|e| e == "json") {
86	                if let Ok(json) = fs::read_to_string(&path) {
87	                    if let Ok(session) = serde_json::from_str::<Session>(&json) {
88	                        sessions.push(session);
89	                    }
90	                }
91	            }
92	        }
93	
94	        // Sort by timestamp descending
95	        sessions.sort_by_key(|s| std::cmp::Reverse(s.id.timestamp()));
96	        sessions.truncate(limit);
97	
98	        Ok(sessions)
99	    }
100	
101	    /// Clean up old sessions (keep last N).
102	    pub fn cleanup(&self, keep: usize) -> Result<usize> {
103	        let sessions = self.list_recent(usize::MAX)?;
104	        let mut removed = 0;
105	
106	        for session in sessions.into_iter().skip(keep) {
107	            let path = self.session_path(&session.id);
108	            if fs::remove_file(&path).is_ok() {
109	                removed += 1;
110	            }
111	        }
112	
113	        Ok(removed)
114	    }
115	
116	    /// Get the store path.
117	    pub fn path(&self) -> &PathBuf {
118	        &self.path
119	    }
120	}
