166	
167	    #[test]
168	    fn session_store_get_latest() {
169	        let temp = TempDir::new().unwrap();
170	        let store = SessionStore::new(temp.path().join("sessions"));
171	
172	        let id1 = SessionId::new();
173	        let mut meta1 = SessionMetadata::new("list", vec![]);
174	        meta1.finalize(0, String::new(), String::new());
175	        store
176	            .save(&Session {
177	                id: id1,
178	                metadata: meta1,
179	            })
180	            .unwrap();
181	
182	        std::thread::sleep(std::time::Duration::from_millis(10));
183	
184	        let id2 = SessionId::new();
185	        let mut meta2 = SessionMetadata::new("run", vec![]);
186	        meta2.finalize(0, String::new(), String::new());
187	        store
188	            .save(&Session {
189	                id: id2.clone(),
190	                metadata: meta2,
191	            })
192	            .unwrap();
193	
194	        let latest = store.get_latest().unwrap().unwrap();
195	        assert_eq!(latest.id, id2);
196	    }
197	
198	    #[test]
199	    fn session_store_cleanup() {
200	        let temp = TempDir::new().unwrap();
201	        let store = SessionStore::new(temp.path().join("sessions"));
202	
203	        // Create 5 sessions
204	        for i in 0..5 {
205	            let id = SessionId::new();
206	            let mut meta = SessionMetadata::new(format!("cmd{}", i), vec![]);
207	            meta.finalize(0, String::new(), String::new());
208	            store.save(&Session { id, metadata: meta }).unwrap();
209	            std::thread::sleep(std::time::Duration::from_millis(5));
210	        }
211	
212	        // Keep only last 2
213	        let removed = store.cleanup(2).unwrap();
214	        assert_eq!(removed, 3);
215	
216	        let remaining = store.list_recent(10).unwrap();
217	        assert_eq!(remaining.len(), 2);
218	    }
