1	//! HTTP template fetching.
2	//!
3	//! Provides an HTTP client for fetching templates from URLs with
4	//! support for ETag-based conditional requests.
5	
6	use crate::error::BivvyError;
7	use reqwest::blocking::Client;
8	use std::time::Duration;
9	
10	type Result<T> = crate::error::Result<T>;
11	
12	/// Default maximum response body size (10 MB).
13	const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
14	
15	/// Fetches templates over HTTP/HTTPS.
16	pub struct HttpFetcher {
17	    client: Client,
18	    timeout: Duration,
19	    max_response_size: u64,
20	}
21	
22	/// Response from fetching a template.
23	#[derive(Debug)]
24	pub struct FetchResponse {
25	    /// The template content.
26	    pub content: String,
27	    /// ETag header if present.
28	    pub etag: Option<String>,
29	    /// Last-Modified header if present.
30	    pub last_modified: Option<String>,
31	}
32	
33	impl HttpFetcher {
34	    /// Create a new HTTP fetcher with default 30-second timeout.
35	    pub fn new() -> Self {
36	        Self::with_timeout(Duration::from_secs(30))
37	    }
38	
39	    /// Create a new HTTP fetcher with custom timeout.
40	    pub fn with_timeout(timeout: Duration) -> Self {
41	        Self {
42	            client: Client::builder()
43	                .user_agent("bivvy")
44	                .timeout(timeout)
45	                .build()
46	                .expect("Failed to build HTTP client"),
47	            timeout,
48	            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
49	        }
50	    }
51	
52	    /// Create a new HTTP fetcher with custom timeout and max response size.
53	    #[cfg(test)]
54	    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
55	        Self {
56	            client: Client::builder()
57	                .user_agent("bivvy")
58	                .timeout(timeout)
59	                .build()
60	                .expect("Failed to build HTTP client"),
61	            timeout,
62	            max_response_size,
63	        }
64	    }
65	
66	    /// Get the configured timeout.
67	    pub fn timeout(&self) -> Duration {
68	        self.timeout
69	    }
70	
71	    /// Fetch a template from a URL.
72	    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
73	        let response = self
74	            .client
75	            .get(url)
76	            .send()
77	            .map_err(|e| BivvyError::RegistryError {
78	                message: format!("HTTP request failed for {}: {}", url, e),
79	            })?;
80	
81	        if !response.status().is_success() {
82	            return Err(BivvyError::RegistryError {
83	                message: format!("HTTP {} fetching {}", response.status(), url),
84	            });
85	        }
86	
87	        // Check Content-Length if available
88	        if let Some(len) = response.content_length() {
89	            if len > self.max_response_size {
90	                return Err(BivvyError::RegistryError {
91	                    message: format!(
92	                        "Response too large ({} bytes, max {} bytes) from {}",
93	                        len, self.max_response_size, url
94	                    ),
95	                });
96	            }
97	        }
98	
99	        let etag = response
100	            .headers()
101	            .get("etag")
102	            .and_then(|v| v.to_str().ok())
103	            .map(String::from);
104	
105	        let last_modified = response
106	            .headers()
107	            .get("last-modified")
108	            .and_then(|v| v.to_str().ok())
109	            .map(String::from);
110	
111	        let content = response.text().map_err(|e| BivvyError::RegistryError {
112	            message: format!("Failed to read response body from {}: {}", url, e),
113	        })?;
114	
115	        // Also check actual content size (in case Content-Length was missing/wrong)
116	        if content.len() as u64 > self.max_response_size {
117	            return Err(BivvyError::RegistryError {
118	                message: format!(
119	                    "Response too large ({} bytes, max {} bytes) from {}",
120	                    content.len(),
121	                    self.max_response_size,
122	                    url
123	                ),
124	            });
125	        }
126	
127	        Ok(FetchResponse {
128	            content,
129	            etag,
130	            last_modified,
131	        })
132	    }
133	
