135	    ///
136	    /// Returns `None` if content unchanged (304 Not Modified).
137	    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
138	        let mut request = self.client.get(url);
