1	//! Git template fetching.
2	//!
3	//! Provides functionality for cloning and updating git repositories
4	//! to fetch templates, with support for specific refs and update detection.
5	
6	use crate::error::BivvyError;
7	use sha2::{Digest, Sha256};
8	use std::path::{Path, PathBuf};
9	
10	type Result<T> = crate::error::Result<T>;
11	
12	/// Allowed URL schemes for git clone operations.
13	///
14	/// Only secure transport protocols are permitted as defense-in-depth:
15	/// - `https://` -- encrypted HTTP transport
16	/// - `ssh://` -- SSH transport
17	/// - `git://` -- native git protocol
18	/// - `git@` -- SCP-style SSH shorthand (e.g. `git@github.com:org/repo.git`)
19	///
20	/// Rejected schemes include `file://` (local filesystem access), `ftp://`,
21	/// and plain `http://` (unencrypted, vulnerable to MITM).
22	pub fn validate_git_url(url: &str) -> Result<()> {
23	    // SCP-style shorthand: git@host:path
24	    if url.starts_with("git@") {
25	        return Ok(());
26	    }
27	
28	    const ALLOWED_SCHEMES: &[&str] = &["https://", "ssh://", "git://"];
29	
30	    for scheme in ALLOWED_SCHEMES {
31	        if url.starts_with(scheme) {
32	            return Ok(());
33	        }
34	    }
35	
36	    return Err(BivvyError::RegistryError {
37	        message: format!(
38	            "Unsupported git URL scheme: {url}\nAllowed schemes: https://, ssh://, git://, and git@ (SCP-style shorthand)"
39	        ),
40	    });
41	}
42	
43	/// Fetches templates from git repositories.
44	pub struct GitFetcher {
45	    /// Directory for cloned repositories.
46	    clone_dir: PathBuf,
47	}
48	
49	/// Information about a git fetch.
50	#[derive(Debug)]
51	pub struct GitFetchResult {
52	    /// Path to the fetched content.
53	    pub local_path: PathBuf,
54	    /// Current commit SHA.
55	    pub commit_sha: String,
56	}
57	
58	impl GitFetcher {
59	    /// Create a new git fetcher.
60	    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
61	        Self {
62	            clone_dir: clone_dir.into(),
63	        }
64	    }
65	
66	    /// Get the clone directory.
67	    pub fn clone_dir(&self) -> &PathBuf {
68	        &self.clone_dir
69	    }
70	
71	    /// Clone or update a repository.
72	    ///
73	    /// Validates the URL scheme before proceeding. Only `https://`, `ssh://`,
74	    /// `git://`, and `git@` SCP-style URLs are allowed.
75	    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
76	        validate_git_url(url)?;
77	        self.fetch_unchecked(url, git_ref)
78	    }
79	
80	    /// Internal fetch without URL validation. Production callers must use
81	    /// [`fetch`](Self::fetch) so the URL scheme is checked first; this is
82	    /// exposed for integration tests that exercise local bare repositories.
83	    pub(crate) fn fetch_unchecked(
84	        &self,
85	        url: &str,
86	        git_ref: Option<&str>,
87	    ) -> Result<GitFetchResult> {
88	        let repo_path = self.repo_path(url);
89	
90	        if repo_path.exists() {
91	            self.update_repo(&repo_path, git_ref)?;
92	        } else {
93	            self.clone_repo(url, &repo_path, git_ref)?;
94	        }
95	
96	        let commit_sha = self.get_head_sha(&repo_path)?;
97	
98	        Ok(GitFetchResult {
99	            local_path: repo_path,
100	            commit_sha,
101	        })
102	    }
103	
104	    /// Check if a repository has new commits.
105	    ///
106	    /// Validates the URL scheme before proceeding.
107	    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
108	        validate_git_url(url)?;
109	        self.has_updates_unchecked(url, git_ref, current_sha)
110	    }
111	
112	    /// Internal has_updates without URL validation.
113	    fn has_updates_unchecked(
114	        &self,
115	        url: &str,
116	        git_ref: Option<&str>,
117	        current_sha: &str,
118	    ) -> Result<bool> {
119	        let remote_sha = self.resolve_ref_unchecked(url, git_ref)?;
120	        Ok(remote_sha != current_sha)
121	    }
122	
123	    /// Get the current commit SHA for a ref using ls-remote.
124	    ///
125	    /// Validates the URL scheme before proceeding.
126	    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
127	        validate_git_url(url)?;
128	        self.resolve_ref_unchecked(url, git_ref)
129	    }
130	
131	    /// Internal resolve_ref without URL validation.
132	    fn resolve_ref_unchecked(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
133	        let refspec = git_ref.unwrap_or("HEAD");
134	
135	        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
136	        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
137	        let candidates = if refspec == "HEAD" {
138	            vec![refspec.to_string()]
139	        } else {
140	            vec![
141	                refspec.to_string(),
142	                format!("refs/heads/{refspec}"),
143	                format!("refs/tags/{refspec}"),
144	            ]
145	        };
146	
147	        for candidate in &candidates {
148	            let output = std::process::Command::new("git")
149	                .args(["ls-remote", url, candidate])
150	                .output()
151	                .map_err(|e| BivvyError::RegistryError {
152	                    message: format!("Failed to run git command: {}", e),
153	                })?;
154	
155	            if !output.status.success() {
156	                return Err(BivvyError::RegistryError {
157	                    message: format!(
158	                        "Failed to query remote: {}",
159	                        String::from_utf8_lossy(&output.stderr)
160	                    ),
161	                });
162	            }
163	
164	            let stdout = String::from_utf8_lossy(&output.stdout);
165	            if let Some(sha) = stdout
166	                .lines()
167	                .next()
168	                .and_then(|line| line.split_whitespace().next())
169	            {
170	                return Ok(sha.to_string());
171	            }
172	        }
173	
174	        return Err(BivvyError::RegistryError {
175	            message: format!("Could not resolve ref '{refspec}' from {url}"),
176	        })
177	    }
178	
179	    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
180	        if let Some(parent) = path.parent() {
181	            std::fs::create_dir_all(parent).map_err(|e| BivvyError::RegistryError {
182	                message: format!("Failed to create directory {:?}: {}", parent, e),
183	            })?;
184	        }
185	
186	        let mut cmd = std::process::Command::new("git");
187	        cmd.args(["clone", "--depth", "1"]);
188	
189	        if let Some(r) = git_ref {
190	            cmd.args(["--branch", r]);
191	        }
192	
193	        cmd.args([url, &path.to_string_lossy()]);
194	
195	        let output = cmd.output().map_err(|e| BivvyError::RegistryError {
196	            message: format!("Failed to run git command: {}", e),
197	        })?;
198	        if !output.status.success() {
199	            return Err(BivvyError::RegistryError {
200	                message: format!(
201	                    "Git clone failed: {}",
202	                    String::from_utf8_lossy(&output.stderr)
203	                ),
204	            });
205	        }
206	
207	        Ok(())
208	    }
209	
210	    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
211	        let output = std::process::Command::new("git")
212	            .args(["fetch", "origin"])
213	            .current_dir(path)
214	            .output()
215	            .map_err(|e| BivvyError::RegistryError {
216	                message: format!("Failed to run git command: {}", e),
217	            })?;
218	
219	        if !output.status.success() {
220	            return Err(BivvyError::RegistryError {
221	                message: format!(
222	                    "Git fetch failed: {}",
223	                    String::from_utf8_lossy(&output.stderr)
