10	
11	/// Current version of bivvy.
12	pub const VERSION: &str = env!("CARGO_PKG_VERSION");
13	
14	/// GitHub API URL for releases.
15	const GITHUB_API_URL: &str = "https://api.github.com/repos/bivvy-dev/bivvy/releases/latest";
16	
17	/// How often to check for updates (1 day).
18	const CHECK_INTERVAL_SECS: i64 = 86400;
19	
20	/// Information about an available update.
21	#[derive(Debug, Clone, Serialize, Deserialize)]
22	pub struct UpdateInfo {
23	    /// Current version.
24	    pub current: String,
25	    /// Latest available version.
26	    pub latest: String,
27	    /// Whether an update is available.
28	    pub update_available: bool,
29	    /// Release URL.
30	    pub release_url: Option<String>,
31	    /// When this check was performed.
32	    pub checked_at: DateTime<Utc>,
33	}
34	
35	/// Cached update check result.
36	#[derive(Debug, Clone, Serialize, Deserialize)]
37	struct UpdateCache {
38	    /// Last update info.
39	    info: UpdateInfo,
40	    /// When the cache was written.
41	    cached_at: DateTime<Utc>,
42	}
43	
44	/// Check for available updates.
45	///
46	/// Returns cached result if within check interval.
47	pub fn check_for_updates() -> Option<UpdateInfo> {
48	    // Check cache first
49	    if let Some(cached) = load_cache() {
50	        let age = Utc::now()
51	            .signed_duration_since(cached.cached_at)
52	            .num_seconds();
53	        if age < CHECK_INTERVAL_SECS {
54	            return Some(cached.info);
55	        }
56	    }
57	
58	    // Fetch latest version
59	    match fetch_latest_version() {
60	        Ok(info) => {
61	            // Cache the result
62	            let _ = save_cache(&info);
63	            Some(info)
64	        }
65	        Err(_) => {
66	            // Return cached result even if expired
67	            load_cache().map(|c| c.info)
68	        }
69	    }
70	}
71	
72	/// Check for updates without using cache.
73	pub fn check_for_updates_fresh() -> Result<UpdateInfo> {
74	    fetch_latest_version()
75	}
76	
77	/// Fetch the latest version from GitHub.
78	fn fetch_latest_version() -> Result<UpdateInfo> {
79	    let client = reqwest::blocking::Client::builder()
80	        .user_agent("bivvy")
81	        .timeout(std::time::Duration::from_secs(10))
82	        .build()
83	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to create HTTP client: {}", e) })?;
84	
85	    let response: serde_json::Value = client
86	        .get(GITHUB_API_URL)
87	        .send()
88	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to check for updates: {}", e) })?
89	        .json()
90	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to parse GitHub API response: {}", e) })?;
91	
92	    let tag = response["tag_name"]
93	        .as_str()
94	        .ok_or_else(|| BivvyError::UpdateError { message: "No tag_name in GitHub API response".into() })?
95	        .trim_start_matches('v');
96	
97	    let release_url = response["html_url"].as_str().map(String::from);
98	
99	    let update_available = is_newer_version(tag, VERSION);
100	
101	    Ok(UpdateInfo {
102	        current: VERSION.to_string(),
103	        latest: tag.to_string(),
104	        update_available,
105	        release_url,
106	        checked_at: Utc::now(),
107	    })
108	}
109	
110	/// Compare versions to check if `latest` is newer than `current`.
111	fn is_newer_version(latest: &str, current: &str) -> bool {
112	    let parse_version = |v: &str| -> Vec<u32> {
113	        v.split('.')
114	            .take(3)
115	            .filter_map(|s| s.parse().ok())
116	            .collect()
117	    };
118	
119	    let latest_parts = parse_version(latest);
120	    let current_parts = parse_version(current);
121	
122	    // Compare component by component
123	    for (l, c) in latest_parts.iter().zip(current_parts.iter()) {
124	        if l > c {
125	            return true;
126	        }
127	        if l < c {
128	            return false;
129	        }
130	    }
131	
132	    // If all components equal, check if latest has more components
133	    latest_parts.len() > current_parts.len()
134	}
135	
136	/// Get the cache file path.
137	fn cache_path() -> Option<PathBuf> {
138	    crate::sys::cache_dir().map(|d| d.join("bivvy").join("update_check.json"))
139	}
140	
141	/// Load cached update info.
142	fn load_cache() -> Option<UpdateCache> {
143	    let path = cache_path()?;
144	    let content = fs::read_to_string(path).ok()?;
145	    serde_json::from_str(&content).ok()
146	}
147	
148	/// Save update info to cache.
149	fn save_cache(info: &UpdateInfo) -> Result<()> {
150	    let path = cache_path().ok_or_else(|| BivvyError::UpdateError { message: "No cache directory".into() })?;
151	
152	    if let Some(parent) = path.parent() {
153	        fs::create_dir_all(parent)
154	            .map_err(|e| BivvyError::UpdateError { message: format!("Failed to save update cache: {}", e) })?;
155	    }
156	
157	    let cache = UpdateCache {
158	        info: info.clone(),
159	        cached_at: Utc::now(),
160	    };
161	
162	    let content = serde_json::to_string_pretty(&cache)
163	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to save update cache: {}", e) })?;
164	    fs::write(path, content)
165	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to save update cache: {}", e) })?;
166	
167	    Ok(())
168	}
169	
170	/// Clear the update check cache.
171	pub fn clear_cache() -> Result<()> {
172	    if let Some(path) = cache_path() {
173	        if path.exists() {
174	            fs::remove_file(path)
175	                .map_err(|e| BivvyError::UpdateError { message: format!("Failed to clear update cache: {}", e) })?;
176	        }
177	    }
178	    Ok(())
179	}
