1	//! Background auto-update functionality.
2	//!
3	//! Provides automatic, zero-interaction updates for bivvy. On each run,
4	//! a background process checks for new versions and either:
5	//! - Runs the package manager update command (cargo/homebrew installs)
6	//! - Downloads and stages a new binary (manual installs)
7	//!
8	//! For manual installs, the staged binary is swapped in on the next startup.
9	//! For package-manager installs, the update is applied immediately by the
10	//! package manager and takes effect on the next invocation.
11	
12	use crate::error::BivvyError;
13	type Result<T> = crate::error::Result<T>;
14	
15	use chrono::{DateTime, Utc};
16	use serde::{Deserialize, Serialize};
17	use std::fs;
18	use std::path::PathBuf;
19	use std::process::{Command, Stdio};
20	
21	use super::version::{check_for_updates, UpdateInfo};
22	use super::{detect_install_method, InstallMethod};
23	
24	/// Metadata for a staged binary update (manual installs only).
25	#[derive(Debug, Clone, Serialize, Deserialize)]
26	pub struct StagedUpdate {
27	    /// The version that was downloaded.
28	    pub version: String,
29	    /// When the binary was staged.
30	    pub staged_at: DateTime<Utc>,
31	}
32	
33	/// Get the staging directory for downloaded binaries.
34	fn staging_dir() -> Option<PathBuf> {
35	    crate::sys::data_dir().map(|d| d.join("bivvy").join("staged-update"))
36	}
37	
38	/// Get the path to the staged binary.
39	fn staged_binary_path() -> Option<PathBuf> {
40	    staging_dir().map(|d| {
41	        if cfg!(windows) {
42	            d.join("bivvy.exe")
43	        } else {
44	            d.join("bivvy")
45	        }
46	    })
47	}
48	
49	/// Get the path to the staging metadata file.
50	fn staged_metadata_path() -> Option<PathBuf> {
51	    staging_dir().map(|d| d.join("metadata.json"))
52	}
53	
54	/// Get the path to the background update lock file.
55	fn lock_path() -> Option<PathBuf> {
56	    crate::sys::cache_dir().map(|d| d.join("bivvy").join("update.lock"))
57	}
58	
59	/// Check if a staged update is ready to apply.
60	pub fn check_staged_update() -> Option<StagedUpdate> {
61	    let meta_path = staged_metadata_path()?;
62	    let content = fs::read_to_string(meta_path).ok()?;
63	    serde_json::from_str(&content).ok()
64	}
65	
66	/// Apply a staged update by replacing the current binary.
67	///
68	/// Only applies to manual installs — for cargo/homebrew, the package manager
69	/// already placed the new binary. Returns the new version string if applied.
70	pub fn apply_staged_update() -> Result<Option<String>> {
71	    let staged = match check_staged_update() {
72	        Some(s) => s,
73	        None => return Ok(None),
74	    };
75	
76	    let method = detect_install_method();
77	
78	    // Staged binary replacement only applies to manual installs.
79	    // For package-manager installs, the manager already updated the binary.
80	    if !matches!(method, InstallMethod::Manual { .. }) {
81	        let _ = clear_staged_update();
82	        return Ok(None);
83	    }
84	
85	    let staged_binary = match staged_binary_path() {
86	        Some(p) if p.exists() => p,
87	        _ => return Ok(None),
88	    };
89	
90	    let current_exe = std::env::current_exe()
91	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to locate current executable: {}", e) })?;
92	
93	    replace_binary(&staged_binary, &current_exe)?;
94	
95	    let _ = clear_staged_update();
96	
97	    Ok(Some(staged.version))
98	}
99	
100	/// Replace the current binary with the staged one (Unix).
101	#[cfg(unix)]
102	fn replace_binary(staged: &PathBuf, current: &PathBuf) -> Result<()> {
103	    use std::os::unix::fs::PermissionsExt;
104	
105	    // Copy to a temp file in the same directory (ensures same-filesystem rename)
106	    let temp = current.with_extension("new");
107	    fs::copy(staged, &temp)
108	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to copy staged binary: {}", e) })?;
109	
110	    // Preserve original permissions and ensure executable
111	    let perms = fs::metadata(current)
112	        .map(|m| m.permissions())
113	        .unwrap_or_else(|_| {
114	            let mut p = fs::metadata(&temp).unwrap().permissions();
115	            p.set_mode(0o755);
116	            p
117	        });
118	    fs::set_permissions(&temp, perms)
119	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to set binary permissions: {}", e) })?;
120	
121	    // Atomic rename
122	    fs::rename(&temp, current)
123	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to replace binary: {}", e) })?;
124	
125	    Ok(())
126	}
127	
128	/// Replace the current binary with the staged one (Windows).
129	#[cfg(windows)]
130	fn replace_binary(staged: &PathBuf, current: &PathBuf) -> Result<()> {
131	    let old = current.with_extension("old.exe");
132	
133	    // Clean up any leftover from a previous update
134	    let _ = fs::remove_file(&old);
135	
136	    // Windows allows renaming a running executable
137	    fs::rename(current, &old)
138	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to rename current binary: {}", e) })?;
139	    fs::copy(staged, current)
140	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to copy new binary into place: {}", e) })?;
141	
142	    // Best-effort cleanup (may fail if old binary is still running)
143	    let _ = fs::remove_file(&old);
144	
145	    Ok(())
146	}
147	
148	/// Remove all staged update files.
149	fn clear_staged_update() -> Result<()> {
150	    if let Some(dir) = staging_dir() {
151	        if dir.exists() {
152	            fs::remove_dir_all(&dir)
153	                .map_err(|e| BivvyError::UpdateError { message: format!("Failed to clear staged update: {}", e) })?;
154	        }
155	    }
156	    Ok(())
157	}
158	
159	/// Check whether a background update process is already running (or ran recently).
160	///
161	/// Uses a lock file with a timestamp. If the lock is less than 5 minutes old,
162	/// we assume the process is still active or just finished.
163	fn is_update_process_running() -> bool {
164	    let path = match lock_path() {
165	        Some(p) => p,
166	        None => return false,
167	    };
168	
169	    if let Ok(meta) = fs::metadata(&path) {
170	        if let Ok(modified) = meta.modified() {
171	            if let Ok(age) = modified.elapsed() {
172	                return age.as_secs() < 300;
173	            }
174	        }
175	    }
176	
177	    false
178	}
179	
180	/// Write a lock file to prevent concurrent background update processes.
181	fn write_lock_file() -> Result<()> {
182	    let path = lock_path().ok_or_else(|| BivvyError::UpdateError { message: "No cache directory for lock file".into() })?;
183	    if let Some(parent) = path.parent() {
184	        fs::create_dir_all(parent)
185	            .map_err(|e| BivvyError::UpdateError { message: format!("Failed to create lock file directory: {}", e) })?;
186	    }
