199	/// Read the `auto_update` setting from the system config (`~/.bivvy/config.yml`).
200	///
201	/// Returns the configured value, or `true` (the default) if the system
202	/// config doesn't exist or doesn't contain the setting.
203	pub fn is_auto_update_enabled() -> bool {
204	    let path = match crate::sys::home_dir() {
205	        Some(h) => h.join(".bivvy").join("config.yml"),
206	        None => return true,
207	    };
208	
209	    let content = match fs::read_to_string(&path) {
210	        Ok(c) => c,
211	        Err(_) => return true, // No system config → default on
212	    };
213	
214	    // Parse just enough to read settings.auto_update
215	    let value: serde_yaml::Value = match serde_yaml::from_str(&content) {
216	        Ok(v) => v,
217	        Err(_) => return true,
218	    };
219	
220	    value
221	        .get("settings")
222	        .and_then(|s| s.get("auto_update"))
223	        .and_then(|v| v.as_bool())
224	        .unwrap_or(true)
225	}
