227	/// Decide whether to spawn a background update process.
228	pub fn should_spawn_background_update(is_interactive: bool, is_ci: bool) -> bool {
229	    // Never auto-update in CI
230	    if is_ci {
231	        return false;
232	    }
233	
234	    // Only auto-update in interactive sessions
235	    if !is_interactive {
236	        return false;
237	    }
238	
239	    // Respect the user's config setting
240	    if !is_auto_update_enabled() {
241	        return false;
242	    }
243	
244	    // Don't spawn if another process is already running
245	    if is_update_process_running() {
246	        return false;
247	    }
248	
249	    // Don't spawn if there's already a staged update waiting
250	    if check_staged_update().is_some() {
251	        return false;
252	    }
253	
254	    true
255	}
