257	/// Spawn a detached background process to check for and apply updates.
258	///
259	/// The background process is the same bivvy binary, invoked with the
260	/// `BIVVY_SELF_UPDATE_BG=1` environment variable. It runs silently
261	/// with no stdin/stdout/stderr.
262	pub fn spawn_background_update() -> Result<()> {
263	    let exe = std::env::current_exe()
264	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to locate current executable: {}", e) })?;
265	
266	    let mut cmd = Command::new(exe);
267	    cmd.env("BIVVY_SELF_UPDATE_BG", "1")
268	        .stdin(Stdio::null())
269	        .stdout(Stdio::null())
270	        .stderr(Stdio::null());
271	
272	    // On Unix, create a new session so the child survives if the parent's
273	    // terminal closes.
274	    #[cfg(unix)]
275	    {
276	        use std::os::unix::process::CommandExt;
277	        unsafe {
278	            cmd.pre_exec(|| {
279	                libc::setsid();
280	                Ok(())
281	            });
282	        }
283	    }
284	
285	    // On Windows, use DETACHED_PROCESS so the child has no console window.
286	    #[cfg(windows)]
287	    {
288	        use std::os::windows::process::CommandExt;
289	        cmd.creation_flags(0x00000008); // DETACHED_PROCESS
290	    }
291	
292	    cmd.spawn()
293	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to spawn background update process: {}", e) })?;
294	
295	    Ok(())
296	}
