313	/// Inner logic for background updates, separated so the lock file
314	/// is always cleaned up regardless of success/failure.
315	fn do_background_update() -> Result<()> {
316	    let info = match check_for_updates() {
317	        Some(info) if info.update_available => info,
318	        _ => return Ok(()),
319	    };
320	
321	    let method = detect_install_method();
322	
323	    match method {
324	        InstallMethod::Cargo => {
325	            run_package_manager_update("cargo", &["install", "bivvy", "--force"])?;
326	        }
327	        InstallMethod::Homebrew => {
328	            run_package_manager_update("brew", &["upgrade", "bivvy"])?;
329	        }
330	        InstallMethod::Manual { .. } => {
331	            stage_binary_update(&info)?;
332	        }
333	        InstallMethod::Unknown => {
334	            // Can't auto-update — silently skip
335	        }
336	    }
337	
338	    Ok(())
339	}
