341	/// Run a package manager's update command silently.
342	fn run_package_manager_update(program: &str, args: &[&str]) -> Result<()> {
343	    let status = Command::new(program)
344	        .args(args)
345	        .stdin(Stdio::null())
346	        .stdout(Stdio::null())
347	        .stderr(Stdio::null())
348	        .status()
349	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to run {} {}: {}", program, args.join(" "), e) })?;
350	
351	    if !status.success() {
352	        return Err(BivvyError::UpdateError {
353	            message: format!("{} {} exited with code {:?}", program, args.join(" "), status.code()),
354	        });
355	    }
356	
357	    Ok(())
358	}
