360	/// Download the appropriate binary from GitHub releases and stage it.
361	fn stage_binary_update(info: &UpdateInfo) -> Result<()> {
362	    let asset_url = find_platform_asset_url(info)?;
363	
364	    let dir = staging_dir().ok_or_else(|| BivvyError::UpdateError { message: "No data directory for staging".into() })?;
365	    fs::create_dir_all(&dir)
366	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to create staging directory: {}", e) })?;
367	
368	    let binary_path = if cfg!(windows) {
369	        dir.join("bivvy.exe")
370	    } else {
371	        dir.join("bivvy")
372	    };
373	
374	    download_asset(&asset_url, &binary_path)?;
375	
376	    // Write metadata so apply_staged_update knows the version
377	    let metadata = StagedUpdate {
378	        version: info.latest.clone(),
379	        staged_at: Utc::now(),
380	    };
381	    let meta_path = dir.join("metadata.json");
382	    fs::write(meta_path, serde_json::to_string_pretty(&metadata)?)?;
383	
384	    Ok(())
385	}
