387	/// Query the GitHub releases API to find the download URL for this platform.
388	fn find_platform_asset_url(info: &UpdateInfo) -> Result<String> {
389	    let target = platform_target();
390	
391	    let client = reqwest::blocking::Client::builder()
392	        .user_agent("bivvy")
393	        .timeout(std::time::Duration::from_secs(30))
394	        .build()?;
395	
396	    let api_url = format!(
397	        "https://api.github.com/repos/bivvy-dev/bivvy/releases/tags/v{}",
398	        info.latest
399	    );
400	
401	    let response: serde_json::Value = client
402	        .get(&api_url)
403	        .send()?
404	        .json()
405	        .context("Failed to parse GitHub releases API response")?;
406	
407	    let assets = response["assets"]
408	        .as_array()
409	        .context("No assets array in release")?;
410	
411	    for asset in assets {
412	        let name = asset["name"].as_str().unwrap_or("");
413	        if name.contains(&target) {
414	            if let Some(url) = asset["browser_download_url"].as_str() {
415	                return Ok(url.to_string());
416	            }
417	        }
418	    }
419	
420	    anyhow::bail!(
421	        "No release asset found for platform '{}' in v{}",
422	        target,
423	        info.latest
424	    )
425	}
