427	/// Return the Rust target triple fragment for this platform.
428	///
429	/// Used to match against GitHub release asset filenames (e.g.
430	/// `bivvy-x86_64-apple-darwin`, `bivvy-aarch64-unknown-linux-gnu`).
431	pub fn platform_target() -> String {
432	    let os = match std::env::consts::OS {
433	        "macos" => "apple-darwin",
434	        "linux" => "unknown-linux-gnu",
435	        "windows" => "pc-windows-msvc",
436	        other => other,
437	    };
438	
439	    let arch = std::env::consts::ARCH;
440	
441	    format!("{}-{}", arch, os)
442	}
