444	/// Download a file from a URL to a local path.
445	fn download_asset(url: &str, dest: &PathBuf) -> Result<()> {
446	    let client = reqwest::blocking::Client::builder()
447	        .user_agent("bivvy")
448	        .timeout(std::time::Duration::from_secs(120))
449	        .build()?;
450	
451	    let bytes = client
452	        .get(url)
453	        .send()
454	        .context("Failed to download update")?
455	        .bytes()
456	        .context("Failed to read download body")?;
457	
458	    fs::write(dest, &bytes)?;
459	
460	    // Make executable on Unix
461	    #[cfg(unix)]
462	    {
463	        use std::os::unix::fs::PermissionsExt;
464	        let mut perms = fs::metadata(dest)?.permissions();
465	        perms.set_mode(0o755);
466	        fs::set_permissions(dest, perms)?;
467	    }
468	
469	    Ok(())
470	}
