11	/// Check for updates and prompt user if update available.
12	///
13	/// Returns true if an update was executed.
14	///
15	/// Requires full `UserInterface` — uses `OutputWriter` (messages),
16	/// `Prompter` (confirm prompt), and `UiState` (interactivity check).
17	pub fn check_and_prompt_update(ui: &mut dyn UserInterface) -> Result<bool> {
18	    // Only check in interactive mode
19	    if !ui.is_interactive() {
20	        return Ok(false);
21	    }
22	
23	    // Check for updates
24	    let info = match check_for_updates() {
25	        Some(info) => info,
26	        None => return Ok(false),
27	    };
28	
29	    // No update available
30	    if !info.update_available {
31	        return Ok(false);
32	    }
33	
34	    // Detect install method
35	    let method = detect_install_method();
36	
37	    // Prompt for update
38	    if prompt_for_update(ui, &info, &method)? {
39	        execute_update(&method)?;
40	        return Ok(true);
41	    }
42	
43	    Ok(false)
44	}
