1	//! Update command implementation.
2	//!
3	//! The `bivvy update` command checks for and installs updates.
4	//! It also provides flags to enable or disable automatic background updates.
5	
6	use crate::error::Result;
7	use crate::ui::{OutputWriter, UserInterface};
8	use crate::updates::{
9	    auto_update::is_auto_update_enabled, check_for_updates_fresh, detect_install_method, VERSION,
10	};
11	
12	use super::dispatcher::{Command, CommandResult};
13	
14	/// Arguments for the `update` command.
15	#[derive(Debug, Clone, Default, clap::Args)]
16	pub struct UpdateArgs {
17	    /// Check for updates without installing
18	    #[arg(long)]
19	    pub check: bool,
20	
21	    /// Enable automatic background updates
22	    #[arg(long, conflicts_with = "disable_auto_update")]
23	    pub enable_auto_update: bool,
24	
25	    /// Disable automatic background updates
26	    #[arg(long, conflicts_with = "enable_auto_update")]
27	    pub disable_auto_update: bool,
28	}
29	
30	/// The update command implementation.
31	pub struct UpdateCommand {
32	    args: UpdateArgs,
33	}
34	
35	impl UpdateCommand {
36	    /// Create a new update command.
37	    pub fn new(args: UpdateArgs) -> Self {
38	        Self { args }
39	    }
40	}
41	
42	impl Command for UpdateCommand {
43	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
44	        // Handle auto-update toggle flags
45	        if self.args.enable_auto_update {
46	            return set_auto_update(ui, true);
47	        }
48	        if self.args.disable_auto_update {
49	            return set_auto_update(ui, false);
50	        }
51	
52	        ui.message(&format!("Current version: {}", VERSION));
53	
54	        // Show auto-update status
55	        if is_auto_update_enabled() {
56	            ui.message("Auto-update: enabled");
57	        } else {
58	            ui.message("Auto-update: disabled");
59	        }
60	
61	        ui.message("Checking for updates...");
62	
63	        let info = match check_for_updates_fresh() {
64	            Ok(info) => info,
65	            Err(e) => {
66	                ui.error(&format!("Failed to check for updates: {}", e));
67	                return Ok(CommandResult::failure(1));
68	            }
69	        };
70	
71	        if !info.update_available {
72	            ui.message("You're on the latest version.");
73	            return Ok(CommandResult::success());
74	        }
75	
76	        ui.message(&format!(
77	            "New version available: {} -> {}",
78	            info.current, info.latest
79	        ));
80	
81	        if self.args.check {
82	            if let Some(url) = &info.release_url {
83	                ui.message(&format!("Release: {}", url));
84	            }
85	            return Ok(CommandResult::success());
86	        }
87	
88	        let method = detect_install_method();
89	
90	        if !method.supports_auto_update() {
91	            ui.message(&format!(
92	                "Auto-update is not supported for {} installs.",
93	                method.name()
94	            ));
95	            if let Some(url) = &info.release_url {
96	                ui.message(&format!("Download the latest version from: {}", url));
97	            }
98	            return Ok(CommandResult::success());
99	        }
100	
101	        let update_cmd = method.update_command().unwrap();
102	        ui.message(&format!("Updating via: {}", update_cmd));
103	
104	        let parts: Vec<&str> = update_cmd.split_whitespace().collect();
105	        let status = std::process::Command::new(parts[0])
106	            .args(&parts[1..])
107	            .status()?;
108	
109	        if status.success() {
110	            ui.message("Update complete!");
111	            Ok(CommandResult::success())
112	        } else {
113	            ui.error("Update failed.");
114	            Ok(CommandResult::failure(1))
115	        }
116	    }
117	}
118	
119	/// Write the auto_update setting to the system config at `~/.bivvy/config.yml`.
120	///
121	/// Only requires `OutputWriter` — displays confirmation messages but does not prompt.
122	fn set_auto_update(ui: &mut dyn OutputWriter, enabled: bool) -> Result<CommandResult> {
123	    let home = crate::sys::home_dir().ok_or_else(|| {
124	        crate::error::BivvyError::Other(anyhow::anyhow!("Could not determine home directory"))
125	    })?;
126	
127	    let config_dir = home.join(".bivvy");
128	    let config_path = config_dir.join("config.yml");
129	
130	    // Read existing config or start fresh
131	    let mut value: serde_yaml::Value = if config_path.exists() {
132	        let content = std::fs::read_to_string(&config_path).map_err(|e| {
133	            crate::error::BivvyError::Other(anyhow::anyhow!(
134	                "Failed to read {}: {}",
135	                config_path.display(),
136	                e
137	            ))
138	        })?;
139	        serde_yaml::from_str(&content)
140	            .unwrap_or(serde_yaml::Value::Mapping(serde_yaml::Mapping::new()))
141	    } else {
142	        serde_yaml::Value::Mapping(serde_yaml::Mapping::new())
143	    };
144	
145	    // Ensure settings mapping exists
146	    let mapping = value.as_mapping_mut().ok_or_else(|| {
147	        crate::error::BivvyError::Other(anyhow::anyhow!("System config is not a YAML mapping"))
148	    })?;
149	
150	    let settings_key = serde_yaml::Value::String("settings".to_string());
151	    if !mapping.contains_key(&settings_key) {
152	        mapping.insert(
153	            settings_key.clone(),
154	            serde_yaml::Value::Mapping(serde_yaml::Mapping::new()),
155	        );
156	    }
157	
158	    let settings = mapping
159	        .get_mut(&settings_key)
160	        .and_then(|v| v.as_mapping_mut())
161	        .ok_or_else(|| {
162	            crate::error::BivvyError::Other(anyhow::anyhow!("settings is not a YAML mapping"))
163	        })?;
164	
165	    settings.insert(
166	        serde_yaml::Value::String("auto_update".to_string()),
167	        serde_yaml::Value::Bool(enabled),
168	    );
169	
170	    // Write back
171	    std::fs::create_dir_all(&config_dir)?;
172	    let yaml = serde_yaml::to_string(&value).map_err(|e| {
173	        crate::error::BivvyError::Other(anyhow::anyhow!("Failed to serialize config: {}", e))
174	    })?;
175	    std::fs::write(&config_path, yaml)?;
176	
177	    if enabled {
178	        ui.message("Automatic background updates enabled.");
179	    } else {
180	        ui.message("Automatic background updates disabled.");
181	    }
182	    ui.message(&format!("Saved to {}", config_path.display()));
183	
184	    Ok(CommandResult::success())
185	}
