1	//! Last command implementation.
2	//!
3	//! The `bivvy last` command shows information about the most recent run
4	//! by reading the most recent JSONL event log file.
5	//!
6	//! # Reading step outcomes
7	//!
8	//! Per-step outcomes are read from `step_outcome` events emitted by the
9	//! runner. Each step produces exactly one such event, with a typed
10	//! [`StepOutcomeKind`] that matches the visual state shown by `bivvy run`.
11	//! The older fine-grained events (`step_completed`, `step_skipped`,
12	//! `step_filtered_out`, `step_decided`, `dependency_blocked`) are still
13	//! emitted for consumers that need timing or decision-reasoning detail,
14	//! but `bivvy last` ignores them — `step_outcome` is the single source
15	//! of truth here.
16	
17	use std::path::{Path, PathBuf};
18	use std::time::Duration;
19	
20	use crate::cli::args::LastArgs;
21	use crate::error::Result;
22	use crate::logging::StepOutcomeKind;
23	use crate::state::ProjectId;
24	use crate::ui::theme::BivvyTheme;
25	use crate::ui::{format_duration, format_relative_time, StatusKind, UserInterface};
26	
27	use super::dispatcher::{Command, CommandResult};
28	
29	/// The last command implementation.
30	pub struct LastCommand {
31	    project_root: PathBuf,
32	    args: LastArgs,
33	}
34	
35	impl LastCommand {
36	    /// Create a new last command.
37	    pub fn new(project_root: &Path, args: LastArgs) -> Self {
38	        Self {
39	            project_root: project_root.to_path_buf(),
40	            args,
41	        }
42	    }
43	
44	    /// Get the project root path.
45	    pub fn project_root(&self) -> &Path {
46	        &self.project_root
47	    }
48	
49	    /// Get the command arguments.
50	    pub fn args(&self) -> &LastArgs {
51	        &self.args
52	    }
53	}
54	
55	/// A single step's terminal state, reconstructed from a `step_outcome` event.
56	#[derive(Debug, Clone, serde::Serialize)]
57	struct LoggedStep {
58	    /// Step name.
59	    name: String,
60	    /// Outcome variant as the snake_case JSON tag (`completed`, `failed`,
61	    /// `satisfied`, `declined`, `filtered_out`, `blocked`).
62	    outcome: String,
63	    /// Human-readable detail (skip reason, error message, block reason).
64	    #[serde(skip_serializing_if = "Option::is_none")]
65	    detail: Option<String>,
66	    /// Execution duration in milliseconds, only present for steps that ran.
67	    #[serde(skip_serializing_if = "Option::is_none")]
68	    duration_ms: Option<u64>,
69	}
70	
71	impl LoggedStep {
72	    fn outcome_kind(&self) -> Option<StepOutcomeKind> {
73	        use std::str::FromStr;
74	        StepOutcomeKind::from_str(&self.outcome).ok()
75	    }
76	}
77	
78	/// A run record reconstructed from JSONL event log data.
79	#[derive(Debug, Clone, serde::Serialize)]
80	struct LogLastRun {
81	    /// When the run occurred.
82	    timestamp: chrono::DateTime<chrono::Utc>,
83	    /// Workflow name.
84	    workflow: String,
85	    /// Whether the workflow succeeded.
86	    success: bool,
87	    /// Whether the user aborted.
88	    aborted: bool,
89	    /// Number of steps that ran (from `WorkflowCompleted.steps_run`).
90	    steps_run_count: usize,
91	    /// Number of steps skipped (from `WorkflowCompleted.steps_skipped`).
92	    steps_skipped_count: usize,
93	    /// Total duration in milliseconds.
94	    duration_ms: u64,
95	    /// Typed terminal outcomes, in emission order.
96	    #[serde(skip_serializing_if = "Vec::is_empty")]
97	    steps: Vec<LoggedStep>,
98	    /// Error from the first failed step.
99	    #[serde(skip_serializing_if = "Option::is_none")]
100	    error: Option<String>,
101	}
102	
103	/// Scan a log directory for runs belonging to `canonical_project`.
104	///
105	/// Iterates JSONL files newest-first (by filename) and returns runs
106	/// reconstructed from `WorkflowCompleted` events. Logs from other projects
107	/// (or logs without a recognizable working directory) are skipped.
108	///
109	/// When `all` is false, returns at most one run — the most recent one
110	/// containing a `WorkflowCompleted` event. The previous implementation
111	/// truncated the file list to a single entry up front, which caused
112	/// `bivvy last` to silently report "No runs recorded" whenever the
113	/// most recent log was from a non-`run` command (e.g. `bivvy status`).
114	fn scan_log_dir(log_dir: &Path, all: bool, canonical_project: &Path) -> Vec<LogLastRun> {
115	    if !log_dir.exists() {
116	        return Vec::new();
117	    }
118	
119	    let mut files: Vec<PathBuf> = std::fs::read_dir(log_dir)
120	        .ok()
121	        .into_iter()
122	        .flatten()
123	        .filter_map(|e| e.ok())
124	        .map(|e| e.path())
125	        .filter(|p| p.extension().is_some_and(|ext| ext == "jsonl"))
126	        .collect();
127	    files.sort();
128	    files.reverse();
129	
130	    let mut runs = Vec::new();
131	    for path in &files {
132	        if !crate::logging::log_belongs_to_project(path, canonical_project) {
133	            continue;
134	        }
135	        if let Some(run) = parse_log_file(path) {
136	            runs.push(run);
137	            if !all {
138	                break;
139	            }
140	        }
141	    }
142	
143	    runs
144	}
145	
146	/// Read runs from the default log directory, scoped to `canonical_project`.
147	fn read_last_runs(all: bool, canonical_project: &Path) -> Vec<LogLastRun> {
148	    scan_log_dir(&crate::logging::default_log_dir(), all, canonical_project)
149	}
150	
151	/// Parse a single JSONL log file into a run record.
152	///
153	/// Reads `step_outcome` events into a typed step list and the
154	/// `workflow_completed` event for run-level summary fields. Returns
155	/// `None` if the file has no `workflow_completed` event — that filters
156	/// out non-`run` sessions like `bivvy status`.
157	fn parse_log_file(path: &Path) -> Option<LogLastRun> {
158	    let content = std::fs::read_to_string(path).ok()?;
159	
160	    let mut workflow_completed: Option<serde_json::Value> = None;
161	    let mut steps: Vec<LoggedStep> = Vec::new();
162	    let mut first_error: Option<String> = None;
163	    let mut session_timestamp: Option<chrono::DateTime<chrono::Utc>> = None;
164	
165	    for line in content.lines() {
166	        let value: serde_json::Value = match serde_json::from_str(line) {
167	            Ok(v) => v,
168	            Err(_) => continue,
169	        };
170	
171	        let event_type = value.get("type").and_then(|t| t.as_str()).unwrap_or("");
172	
173	        match event_type {
174	            "session_started" if session_timestamp.is_none() => {
175	                session_timestamp = value
176	                    .get("ts")
177	                    .and_then(|t| t.as_str())
178	                    .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
179	                    .map(|dt| dt.with_timezone(&chrono::Utc));
180	            }
181	            "step_outcome" => {
182	                let name = match value.get("name").and_then(|n| n.as_str()) {
183	                    Some(n) => n.to_string(),
184	                    None => continue,
185	                };
186	                let outcome = match value.get("outcome").and_then(|o| o.as_str()) {
187	                    Some(o) => o.to_string(),
188	                    None => continue,
189	                };
190	                let detail = value
191	                    .get("detail")
192	                    .and_then(|d| d.as_str())
193	                    .map(|s| s.to_string());
194	                let duration_ms = value.get("duration_ms").and_then(|d| d.as_u64());
195	
196	                if first_error.is_none() && outcome == StepOutcomeKind::Failed.as_str() {
197	                    first_error = detail.clone();
198	                }
199	
200	                steps.push(LoggedStep {
201	                    name,
202	                    outcome,
203	                    detail,
204	                    duration_ms,
205	                });
206	            }
207	            "workflow_completed" => {
208	                workflow_completed = Some(value);
209	            }
210	            _ => {}
211	        }
212	    }
213	
214	    let wc = workflow_completed?;
215	
216	    let timestamp = wc
217	        .get("ts")
218	        .and_then(|t| t.as_str())
219	        .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
220	        .map(|dt| dt.with_timezone(&chrono::Utc))
221	        .or(session_timestamp)
222	        .unwrap_or_else(chrono::Utc::now);
223	
224	    let success = wc.get("success").and_then(|v| v.as_bool()).unwrap_or(false);
225	
226	    Some(LogLastRun {
227	        timestamp,
228	        workflow: wc
229	            .get("name")
230	            .and_then(|v| v.as_str())
231	            .unwrap_or("unknown")
232	            .to_string(),
233	        success,
234	        aborted: wc.get("aborted").and_then(|v| v.as_bool()).unwrap_or(false),
235	        steps_run_count: wc.get("steps_run").and_then(|v| v.as_u64()).unwrap_or(0) as usize,
236	        steps_skipped_count: wc
237	            .get("steps_skipped")
238	            .and_then(|v| v.as_u64())
239	            .unwrap_or(0) as usize,
240	        duration_ms: wc.get("duration_ms").and_then(|v| v.as_u64()).unwrap_or(0),
241	        steps,
242	        error: if success { None } else { first_error },
243	    })
244	}
245	
246	/// Map a [`StepOutcomeKind`] to the [`StatusKind`] used to render its glyph
247	/// in `bivvy last`. Matches what `bivvy run` displays for each outcome.
248	fn outcome_status_kind(kind: StepOutcomeKind) -> StatusKind {
249	    match kind {
250	        StepOutcomeKind::Completed | StepOutcomeKind::Satisfied => StatusKind::Success,
251	        StepOutcomeKind::Failed => StatusKind::Failed,
252	        StepOutcomeKind::Declined | StepOutcomeKind::FilteredOut => StatusKind::Skipped,
253	        StepOutcomeKind::Blocked => StatusKind::Blocked,
254	    }
255	}
256	
257	/// Default human-readable label for each outcome when no detail is recorded.
258	fn outcome_default_label(kind: StepOutcomeKind) -> &'static str {
259	    match kind {
260	        StepOutcomeKind::Completed => "completed",
261	        StepOutcomeKind::Failed => "failed",
262	        StepOutcomeKind::Satisfied => "already satisfied",
263	        StepOutcomeKind::Declined => "skipped",
264	        StepOutcomeKind::FilteredOut => "filtered out",
265	        StepOutcomeKind::Blocked => "blocked",
266	    }
267	}
268	
269	impl LastCommand {
270	    /// Display a single run record with styled output.
271	    fn display_run(
272	        &self,
273	        ui: &mut dyn UserInterface,
274	        run: &LogLastRun,
275	        theme: &BivvyTheme,
276	        header_label: &str,
277	    ) {
278	        // Header
279	        ui.message(&format!(
280	            "\n  {} {}\n",
281	            theme.header.apply_to("⛺"),
282	            theme.highlight.apply_to(header_label),
283	        ));
284	
285	        // Key-value metadata
286	        ui.message(&format!(
287	            "  {}  {}",
288	            theme.key.apply_to("Workflow:"),
289	            run.workflow,
290	        ));
291	
292	        ui.message(&format!(
293	            "  {}      {} {}",
294	            theme.key.apply_to("When:"),
295	            format_relative_time(run.timestamp),
296	            theme
297	                .dim
298	                .apply_to(format!("({})", run.timestamp.format("%Y-%m-%d %H:%M:%S"))),
299	        ));
300	
301	        ui.message(&format!(
302	            "  {}  {}",
303	            theme.key.apply_to("Duration:"),
304	            theme
305	                .duration
306	                .apply_to(format_duration(Duration::from_millis(run.duration_ms))),
307	        ));
308	
309	        let status_kind = if run.success {
310	            StatusKind::Success
311	        } else {
312	            StatusKind::Failed
313	        };
314	        let status_label = if run.success {
315	            "Success"
316	        } else if run.aborted {
317	            "Interrupted"
318	        } else {
319	            "Failed"
320	        };
321	        ui.message(&format!(
322	            "  {}    {} {}",
323	            theme.key.apply_to("Status:"),
324	            status_kind.styled(theme),
325	            status_label,
326	        ));
327	
328	        // Steps section — apply --step filter if provided
329	        let step_filter = self.args.step.as_deref();
330	        let steps: Vec<&LoggedStep> = if let Some(filter) = step_filter {
331	            run.steps.iter().filter(|s| s.name == filter).collect()
332	        } else {
333	            run.steps.iter().collect()
334	        };
335	
336	        if !steps.is_empty() {
337	            ui.message("");
338	            ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
339	
340	            for step in &steps {
341	                let kind = step.outcome_kind();
342	                let status_kind = kind.map(outcome_status_kind).unwrap_or(StatusKind::Pending);
343	                let label = step.detail.clone().unwrap_or_else(|| {
344	                    kind.map(outcome_default_label)
345	                        .unwrap_or(step.outcome.as_str())
346	                        .to_string()
347	                });
348	                let duration_info = step
349	                    .duration_ms
350	                    .map(|ms| {
351	                        theme
352	                            .duration
353	                            .apply_to(format_duration(Duration::from_millis(ms)))
354	                            .to_string()
355	                    })
356	                    .unwrap_or_default();
357	
358	                ui.message(&format!(
359	                    "    {} {:<20} {} {}",
360	                    status_kind.styled(theme),
361	                    step.name,
362	                    theme.dim.apply_to(&label),
363	                    duration_info,
364	                ));
365	
366	                // --output: show captured output if available
367	                if self.args.output {
368	                    ui.message(&format!(
369	                        "      {}",
370	                        theme
371	                            .dim
372	                            .apply_to("(no captured output available in run history)")
373	                    ));
374	                }
375	            }
376	        }
377	
378	        // Error detail
379	        if let Some(ref error) = run.error {
380	            ui.message("");
381	            ui.error(&format!("  Error: {}", error));
382	        }
383	    }
384	}
