386	impl Command for LastCommand {
387	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
388	        let project_id = ProjectId::from_path(&self.project_root)?;
389	        let canonical_project = project_id.path();
390	
391	        // --all: show all runs instead of just the last one
392	        if self.args.all {
393	            let runs = read_last_runs(true, canonical_project);
394	
395	            if runs.is_empty() {
396	                ui.message("No runs recorded for this project.");
397	                return Ok(CommandResult::success());
398	            }
399	
400	            // --json with --all: serialize all runs
401	            if self.args.json {
402	                let json = serde_json::to_string_pretty(&runs)
403	                    .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
404	                ui.message(&json);
405	                return Ok(CommandResult::success());
406	            }
407	
408	            let theme = BivvyTheme::new();
409	            for (i, run) in runs.iter().enumerate() {
410	                let label = format!("Run {} of {}", i + 1, runs.len());
411	                self.display_run(ui, run, &theme, &label);
412	            }
413	
414	            return Ok(CommandResult::success());
415	        }
416	
417	        let runs = read_last_runs(false, canonical_project);
418	        let last_run = match runs.first() {
419	            Some(r) => r,
420	            None => {
421	                ui.message("No runs recorded for this project.");
422	                return Ok(CommandResult::success());
423	            }
424	        };
425	
426	        // --step: validate that the step exists in the run
427	        if let Some(ref step_name) = self.args.step {
428	            let in_run = last_run.steps.iter().any(|s| s.name == *step_name);
429	            if !in_run {
430	                ui.error(&format!(
431	                    "Step '{}' was not part of the last run.",
432	                    step_name
433	                ));
434	                return Ok(CommandResult::failure(1));
435	            }
436	        }
437	
438	        // --json: serialize run data as JSON
439	        if self.args.json {
440	            let json = serde_json::to_string_pretty(last_run)
441	                .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
442	            ui.message(&json);
443	            return Ok(CommandResult::success());
444	        }
445	
446	        let theme = BivvyTheme::new();
447	        self.display_run(ui, last_run, &theme, "Last Run");
448	
449	        Ok(CommandResult::success())
450	    }
451	}
