466	/// Convert a requirement status to JSON-friendly strings.
467	fn json_requirement_status(status: &RequirementStatus) -> (&'static str, Option<String>) {
468	    match status {
469	        RequirementStatus::Satisfied => ("satisfied", None),
470	        RequirementStatus::SystemOnly { warning, .. } => ("warning", Some(warning.clone())),
471	        RequirementStatus::Inactive {
472	            manager,
473	            activation_hint,
474	            ..
475	        } => (
476	            "warning",
477	            Some(format!("{} not activated ({})", manager, activation_hint)),
478	        ),
479	        RequirementStatus::ServiceDown { start_hint, .. } => ("missing", Some(start_hint.clone())),
480	        RequirementStatus::Missing { install_hint, .. } => (
481	            "missing",
482	            install_hint
483	                .clone()
484	                .or_else(|| Some("not installed".to_string())),
485	        ),
486	        RequirementStatus::Unknown => ("unknown", Some("unknown requirement".to_string())),
487	    }
488	}
489	
490	/// Format a requirement status for display.
491	fn format_requirement_status(theme: &BivvyTheme, status: &RequirementStatus) -> (String, String) {
492	    match status {
493	        RequirementStatus::Satisfied => (
494	            theme.success.apply_to("✓").to_string(),
495	            theme.dim.apply_to("available").to_string(),
496	        ),
497	        RequirementStatus::SystemOnly { warning, .. } => (
498	            theme.warning.apply_to("⚠").to_string(),
499	            theme.warning.apply_to(warning).to_string(),
500	        ),
501	        RequirementStatus::Inactive {
502	            manager,
503	            activation_hint,
504	            ..
505	        } => (
506	            theme.warning.apply_to("⚠").to_string(),
507	            theme
508	                .warning
509	                .apply_to(format!("{} not activated ({})", manager, activation_hint))
510	                .to_string(),
511	        ),
512	        RequirementStatus::ServiceDown { start_hint, .. } => (
513	            theme.error.apply_to("✗").to_string(),
514	            theme.error.apply_to(start_hint).to_string(),
515	        ),
516	        RequirementStatus::Missing { install_hint, .. } => {
517	            let hint = install_hint.as_deref().unwrap_or("not installed");
518	            (
519	                theme.error.apply_to("✗").to_string(),
520	                theme.error.apply_to(hint).to_string(),
521	            )
522	        }
523	        RequirementStatus::Unknown => (
524	            theme.dim.apply_to("?").to_string(),
525	            theme.dim.apply_to("unknown requirement").to_string(),
526	        ),
527	    }
528	}
