45	impl HistoryCommand {
46	    /// Parse a duration string like "1h", "7d", "30m" into a chrono Duration.
47	    fn parse_since(s: &str) -> Option<chrono::Duration> {
48	        let s = s.trim();
49	        if s.is_empty() {
50	            return None;
51	        }
52	
53	        let (num_str, unit) = s.split_at(s.len() - 1);
54	        let num: i64 = num_str.parse().ok()?;
55	
56	        match unit {
57	            "m" => Some(chrono::Duration::minutes(num)),
58	            "h" => Some(chrono::Duration::hours(num)),
59	            "d" => Some(chrono::Duration::days(num)),
60	            "w" => Some(chrono::Duration::weeks(num)),
61	            _ => None,
62	        }
63	    }
64	
65	    /// Format a single run entry line with theme styling.
66	    fn format_run_line(run: &LogRunRecord, theme: &BivvyTheme) -> String {
67	        let kind = if run.success {
68	            StatusKind::Success
69	        } else {
70	            StatusKind::Failed
71	        };
72	
73	        format!(
74	            "    {}  {:<18} {:<12} {} {}  {}",
75	            kind.styled(theme),
76	            theme.dim.apply_to(format_relative_time(run.timestamp)),
77	            run.workflow,
78	            run.steps_run,
79	            theme
80	                .dim
81	                .apply_to(if run.steps_run == 1 { "step" } else { "steps" }),
82	            theme
83	                .duration
84	                .apply_to(format_duration(Duration::from_millis(run.duration_ms))),
85	        )
86	    }
87	
88	    /// Show detailed info for a run.
89	    fn show_run_detail(ui: &mut dyn OutputWriter, run: &LogRunRecord, theme: &BivvyTheme) {
90	        ui.message(&format!(
91	            "        {} steps run, {} skipped{}",
92	            run.steps_run,
93	            run.steps_skipped,
94	            if run.aborted { " (aborted)" } else { "" },
95	        ));
96	        if let Some(ref log_file) = run.log_file {
97	            ui.message(&format!(
98	                "        {} {}",
99	                theme.dim.apply_to("Log:"),
100	                theme.dim.apply_to(log_file),
101	            ));
102	        }
103	    }
104	}
