106	/// A run record extracted from a JSONL event log.
107	#[derive(Debug, Clone, serde::Serialize)]
108	struct LogRunRecord {
109	    /// When the run occurred (from log file timestamp).
110	    timestamp: chrono::DateTime<chrono::Utc>,
111	    /// Workflow name.
112	    workflow: String,
113	    /// Whether the workflow succeeded.
114	    success: bool,
115	    /// Whether the user aborted.
116	    aborted: bool,
117	    /// Number of steps that ran.
118	    steps_run: usize,
119	    /// Number of steps skipped.
120	    steps_skipped: usize,
121	    /// Total duration in milliseconds.
122	    duration_ms: u64,
123	    /// Log file name (for detail view).
124	    #[serde(skip)]
125	    log_file: Option<String>,
126	}
127	
128	/// Scan a log directory for `WorkflowCompleted` events belonging to
129	/// `canonical_project`.
130	///
131	/// Returns records sorted by timestamp (most recent first). Logs from other
132	/// projects (or logs without a recognizable working directory) are skipped.
133	fn scan_log_dir(log_dir: &Path, limit: usize, canonical_project: &Path) -> Vec<LogRunRecord> {
134	    if !log_dir.exists() {
135	        return Vec::new();
136	    }
137	
138	    // Collect and sort JSONL files by name (descending = most recent first)
139	    let mut files: Vec<PathBuf> = std::fs::read_dir(log_dir)
140	        .ok()
141	        .into_iter()
142	        .flatten()
143	        .filter_map(|e| e.ok())
144	        .map(|e| e.path())
145	        .filter(|p| p.extension().is_some_and(|ext| ext == "jsonl"))
146	        .collect();
147	    files.sort();
148	    files.reverse();
149	
150	    let mut records = Vec::new();
151	    for path in &files {
152	        if records.len() >= limit {
153	            break;
154	        }
155	        if !crate::logging::log_belongs_to_project(path, canonical_project) {
156	            continue;
157	        }
158	        if let Ok(content) = std::fs::read_to_string(path) {
159	            for line in content.lines() {
160	                if let Ok(value) = serde_json::from_str::<serde_json::Value>(line) {
161	                    if value.get("type").and_then(|t| t.as_str()) == Some("workflow_completed") {
162	                        let timestamp = value
163	                            .get("ts")
164	                            .and_then(|t| t.as_str())
165	                            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
166	                            .map(|dt| dt.with_timezone(&chrono::Utc))
167	                            .unwrap_or_else(|| {
168	                                // Fall back to parsing filename timestamp
169	                                parse_log_filename_timestamp(path).unwrap_or_else(chrono::Utc::now)
170	                            });
171	
172	                        records.push(LogRunRecord {
173	                            timestamp,
174	                            workflow: value
175	                                .get("name")
176	                                .and_then(|v| v.as_str())
177	                                .unwrap_or("unknown")
178	                                .to_string(),
179	                            success: value
180	                                .get("success")
181	                                .and_then(|v| v.as_bool())
182	                                .unwrap_or(false),
183	                            aborted: value
184	                                .get("aborted")
185	                                .and_then(|v| v.as_bool())
186	                                .unwrap_or(false),
187	                            steps_run: value.get("steps_run").and_then(|v| v.as_u64()).unwrap_or(0)
188	                                as usize,
189	                            steps_skipped: value
190	                                .get("steps_skipped")
191	                                .and_then(|v| v.as_u64())
192	                                .unwrap_or(0) as usize,
193	                            duration_ms: value
194	                                .get("duration_ms")
195	                                .and_then(|v| v.as_u64())
196	                                .unwrap_or(0),
197	                            log_file: path.file_name().and_then(|f| f.to_str()).map(String::from),
198	                        });
199	                    }
200	                }
201	            }
202	        }
203	    }
204	
205	    records
206	}
207	
208	/// Scan the default log directory, scoped to `canonical_project`.
209	fn scan_log_files(limit: usize, canonical_project: &Path) -> Vec<LogRunRecord> {
210	    scan_log_dir(&crate::logging::default_log_dir(), limit, canonical_project)
211	}
212	
213	/// Parse a timestamp from a log filename like `2026-04-25T10-00-00_hash.jsonl`.
214	fn parse_log_filename_timestamp(path: &Path) -> Option<chrono::DateTime<chrono::Utc>> {
215	    let stem = path.file_stem()?.to_str()?;
216	    // Format: YYYY-MM-DDTHH-MM-SS_suffix
217	    let ts_part = stem.split('_').next()?;
218	    // Convert back to RFC 3339: replace dashes in time part with colons
219	    let rfc3339 = format!("{}Z", ts_part.replacen('-', ":", 2));
220	    chrono::DateTime::parse_from_rfc3339(&rfc3339)
221	        .ok()
222	        .map(|dt| dt.with_timezone(&chrono::Utc))
223	}
