225	impl HistoryCommand {
226	    /// Delete every JSONL log file under `~/.bivvy/logs/` whose
227	    /// `session_started.working_directory` matches this project. Logs from
228	    /// other projects, and any non-JSONL files, are left untouched.
229	    fn clear_history(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
230	        self.clear_history_in(&crate::logging::default_log_dir(), ui)
231	    }
232	
233	    /// Like [`Self::clear_history`] but scoped to a specific log directory.
234	    /// Exists so tests can verify the prompt + deletion flow without touching
235	    /// the user's real `~/.bivvy/logs/`.
236	    fn clear_history_in(
237	        &self,
238	        log_dir: &Path,
239	        ui: &mut dyn UserInterface,
240	    ) -> Result<CommandResult> {
241	        let project_id = crate::state::ProjectId::from_path(&self.project_root)?;
242	        let logs = crate::logging::list_project_logs(log_dir, project_id.path());
243	        let count = logs.len();
244	        if count == 0 {
245	            ui.message("No run history to clear for this project.");
246	            return Ok(CommandResult::success());
247	        }
248	
249	        if !self.args.force && ui.is_interactive() {
250	            let prompt = Prompt {
251	                key: "clear_history".to_string(),
252	                question: format!(
253	                    "Clear {} run log{} for this project?",
254	                    count,
255	                    if count == 1 { "" } else { "s" },
256	                ),
257	                prompt_type: PromptType::Confirm,
258	                default: Some("false".to_string()),
259	            };
260	
261	            match ui.prompt(&prompt)? {
262	                PromptResult::Bool(true) => {}
263	                _ => {
264	                    ui.message("Cancelled");
265	                    return Ok(CommandResult::success());
266	                }
267	            }
268	        }
269	
270	        let mut deleted = 0usize;
271	        for path in &logs {
272	            if std::fs::remove_file(path).is_ok() {
273	                deleted += 1;
274	            }
275	        }
276	        ui.success(&format!(
277	            "Cleared {} run log{} for this project",
278	            deleted,
279	            if deleted == 1 { "" } else { "s" },
280	        ));
281	        Ok(CommandResult::success())
282	    }
283	}
284	
285	impl Command for HistoryCommand {
286	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
287	        if self.args.clear {
288	            return self.clear_history(ui);
289	        }
290	
291	        let limit = self.args.limit.unwrap_or(10);
292	        let project_id = crate::state::ProjectId::from_path(&self.project_root)?;
293	        let mut records = scan_log_files(limit.max(100), project_id.path()); // scan more, filter later
294	
295	        // Apply --since filter
296	        if let Some(ref since_str) = self.args.since {
297	            if let Some(duration) = Self::parse_since(since_str) {
298	                let cutoff = chrono::Utc::now() - duration;
299	                records.retain(|r| r.timestamp >= cutoff);
300	            }
301	        }
302	
303	        // Apply --step filter: not available from JSONL (WorkflowCompleted
304	        // only has counts, not step names). Show a note.
305	        if self.args.step.is_some() {
306	            ui.message("Note: --step filter is not yet supported with event log history.");
307	        }
308	
309	        // Apply limit
310	        records.truncate(limit);
311	
312	        if records.is_empty() {
313	            ui.message("No run history for this project.");
314	            return Ok(CommandResult::success());
315	        }
316	
317	        // JSON output mode
318	        if self.args.json {
319	            let json = serde_json::to_string_pretty(&records)
320	                .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
321	            ui.message(&json);
322	            return Ok(CommandResult::success());
323	        }
324	
325	        let theme = BivvyTheme::new();
326	
327	        ui.message(&format!(
328	            "\n  {} {}\n",
329	            theme.header.apply_to("⛺"),
330	            theme.highlight.apply_to("Run History"),
331	        ));
332	
333	        for run in &records {
334	            let line = Self::format_run_line(run, &theme);
335	            ui.message(&line);
336	
337	            if self.args.detail {
338	                Self::show_run_detail(ui, run, &theme);
339	            }
340	        }
341	
342	        Ok(CommandResult::success())
343	    }
344	}
