pub fn parse_ttl(ttl: &str) -> Result<Duration> {
    let ttl = ttl.trim().to_lowercase();
    let parse_num = |s: &str| -> Result<i64> {
        s.parse().map_err(|e| BivvyError::CacheError {
            message: format!("Invalid TTL value '{}': {}", s, e),
        })
    };

    if let Some(days) = ttl.strip_suffix('d') {
        let n = parse_num(days)?;
        Ok(Duration::days(n))
    } else if let Some(hours) = ttl.strip_suffix('h') {
        let n = parse_num(hours)?;
        Ok(Duration::hours(n))
    } else if let Some(mins) = ttl.strip_suffix('m') {
        let n = parse_num(mins)?;
        Ok(Duration::minutes(n))
    } else if let Some(secs) = ttl.strip_suffix('s') {
        let n = parse_num(secs)?;
        Ok(Duration::seconds(n))
    } else {
        // Assume seconds if no suffix
        let n = parse_num(&ttl)?;
        Ok(Duration::seconds(n))
    }
}

