//! Cache revalidation for ETag and git strategies.

use super::{CacheEntry, CacheStore, ValidationResult};
use crate::error::BivvyError;
use crate::registry::fetch::{GitFetcher, HttpFetcher};

type Result<T> = crate::error::Result<T>;

/// Performs cache revalidation using ETag or git checking.
pub struct CacheRevalidator<'a> {
    store: &'a CacheStore,
    http: HttpFetcher,
    git: GitFetcher,
}

/// Result of revalidation.
#[derive(Debug)]
pub enum RevalidationResult {
    /// Content unchanged, cache extended.
    Unchanged,
    /// Content changed, new content available.
    Updated(String),
    /// Revalidation failed (fallback to cache or error).
    Failed(String),
}

impl<'a> CacheRevalidator<'a> {
    /// Create a new revalidator.
    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
        Self {
            store,
            http: HttpFetcher::new(),
            git: GitFetcher::new(git_clone_dir),
        }
    }

    /// Revalidate an entry using its ETag.
    pub fn revalidate_etag(
        &self,
        url: &str,
        entry: &mut CacheEntry,
        new_ttl_seconds: u64,
    ) -> Result<RevalidationResult> {
        let etag = entry.metadata.etag.as_deref();

        match self.http.fetch_if_changed(url, etag)? {
            None => {
                // 304 Not Modified - extend TTL
                entry.metadata.expires_at =
                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
                self.store.update(entry)?;
                Ok(RevalidationResult::Unchanged)
            }
            Some(response) => {
                // Content changed - update cache
                let content_path = self
                    .store
                    .content_path(&entry.source_id, &entry.template_name);
                std::fs::write(&content_path, &response.content).map_err(|e| {
                    BivvyError::CacheError {
                        message: format!("Failed to write cache content: {}", e),
                    }
                })?;

                entry.metadata.etag = response.etag;
                entry.metadata.size_bytes = response.content.len() as u64;
                entry.metadata.cached_at = chrono::Utc::now();
                entry.metadata.expires_at =
                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
                self.store.update(entry)?;

                Ok(RevalidationResult::Updated(response.content))
            }
        }
    }

    /// Revalidate an entry using git commit comparison.
    pub fn revalidate_git(
        &self,
        url: &str,
        git_ref: Option<&str>,
        entry: &mut CacheEntry,
        new_ttl_seconds: u64,
    ) -> Result<RevalidationResult> {
        let current_sha = match &entry.metadata.commit_sha {
            Some(sha) => sha.clone(),
            None => {
                // No SHA to compare, must re-fetch
                return self.fetch_git(url, git_ref, entry, new_ttl_seconds);
            }
        };

        let has_updates = self.git.has_updates(url, git_ref, &current_sha)?;

        if has_updates {
            self.fetch_git(url, git_ref, entry, new_ttl_seconds)
        } else {
            // No updates - extend TTL
            entry.metadata.expires_at =
                chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
            self.store.update(entry)?;
            Ok(RevalidationResult::Unchanged)
        }
    }

    /// Fetch from git and update the cache entry.
    fn fetch_git(
        &self,
        url: &str,
        git_ref: Option<&str>,
        entry: &mut CacheEntry,
        new_ttl_seconds: u64,
    ) -> Result<RevalidationResult> {
        let result = self.git.fetch(url, git_ref)?;

        // Copy content from cloned repo to cache
        let content_path = self
            .store
            .content_path(&entry.source_id, &entry.template_name);

        // For git sources, we store a marker that the content is at the git path
        let content = format!("git-path:{}", result.local_path.display());
        std::fs::write(&content_path, &content).map_err(|e| BivvyError::CacheError {
            message: format!("Failed to write cache content: {}", e),
        })?;

        entry.metadata.commit_sha = Some(result.commit_sha);
        entry.metadata.cached_at = chrono::Utc::now();
        entry.metadata.expires_at =
            chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
        self.store.update(entry)?;

        Ok(RevalidationResult::Updated(content))
    }
}

/// Check if a validation result needs revalidation.
pub fn needs_revalidation(result: &ValidationResult) -> bool {
    matches!(result, ValidationResult::NeedsRevalidation)
}

#[cfg(test)]
mod tests {
    use super::*;
    use httpmock::prelude::*;
    use tempfile::TempDir;

    #[test]
    fn needs_revalidation_check() {
        assert!(!needs_revalidation(&ValidationResult::Fresh));
        assert!(!needs_revalidation(&ValidationResult::Expired));
        assert!(needs_revalidation(&ValidationResult::NeedsRevalidation));
        assert!(!needs_revalidation(&ValidationResult::NotFound));
    }

    #[test]
    fn revalidator_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let git_dir = temp.path().join("git");
        let _revalidator = CacheRevalidator::new(&store, git_dir);
    }

    #[test]
    fn revalidation_result_variants() {
        let unchanged = RevalidationResult::Unchanged;
        let updated = RevalidationResult::Updated("new content".to_string());
        let failed = RevalidationResult::Failed("network error".to_string());

        // Just check we can pattern match
        match unchanged {
            RevalidationResult::Unchanged => {}
            _ => panic!("expected Unchanged"),
        }

        match updated {
            RevalidationResult::Updated(content) => assert_eq!(content, "new content"),
            _ => panic!("expected Updated"),
        }

        match failed {
            RevalidationResult::Failed(msg) => assert_eq!(msg, "network error"),
            _ => panic!("expected Failed"),
        }
    }

    // --- Mock HTTP revalidation tests ---

    #[test]
    fn etag_revalidation_unchanged_on_304() {
        let server = MockServer::start();

        let mock = server.mock(|when, then| {
            when.method(GET)
                .path("/template.yml")
                .header("If-None-Match", "\"etag-v1\"");
            then.status(304);
        });

        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        let git_dir = temp.path().join("git");
        let revalidator = CacheRevalidator::new(&store, git_dir);

        // Create an expired cache entry with an etag
        let mut entry = store
            .store("http:test", "template", "old content", 0)
            .unwrap();
        entry.metadata.etag = Some("\"etag-v1\"".to_string());
        store.update(&entry).unwrap();

        let result = revalidator
            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
            .unwrap();

        mock.assert();
        assert!(matches!(result, RevalidationResult::Unchanged));
        // TTL should be extended
        assert!(!entry.is_expired());
    }

    #[test]
    fn etag_revalidation_updated_on_200() {
        let server = MockServer::start();

        server.mock(|when, then| {
            when.method(GET).path("/template.yml");
            then.status(200)
                .header("ETag", "\"etag-v2\"")
                .body("new content");
        });

        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        let git_dir = temp.path().join("git");
        let revalidator = CacheRevalidator::new(&store, git_dir);

        // Create an expired cache entry with an old etag
        let mut entry = store
            .store("http:test", "template", "old content", 0)
            .unwrap();
        entry.metadata.etag = Some("\"etag-v1\"".to_string());
        store.update(&entry).unwrap();

        let result = revalidator
            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
            .unwrap();

        match result {
            RevalidationResult::Updated(content) => {
                assert_eq!(content, "new content");
            }
            other => panic!("Expected Updated, got {:?}", other),
        }

        // ETag should be updated
        assert_eq!(entry.metadata.etag, Some("\"etag-v2\"".to_string()));
        // TTL should be extended
        assert!(!entry.is_expired());
    }

    #[test]
    fn etag_revalidation_updates_cached_content_on_disk() {
        let server = MockServer::start();

        server.mock(|when, then| {
            when.method(GET).path("/template.yml");
            then.status(200)
                .header("ETag", "\"etag-v2\"")
                .body("updated content on disk");
        });

        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        let git_dir = temp.path().join("git");
        let revalidator = CacheRevalidator::new(&store, git_dir);

        let mut entry = store
            .store("http:test", "template", "old content", 0)
            .unwrap();
        entry.metadata.etag = Some("\"etag-v1\"".to_string());
        store.update(&entry).unwrap();

        revalidator
            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
            .unwrap();

        // Verify content on disk is updated
        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "updated content on disk");
    }
}

//! Cache validation and invalidation logic.

use chrono::{Duration, Utc};

use super::{CacheEntry, CacheStore};
use crate::error::BivvyError;
use crate::registry::source::RemoteCacheStrategy;

type Result<T> = crate::error::Result<T>;

/// Cache validator for checking entry freshness.
pub struct CacheValidator<'a> {
    store: &'a CacheStore,
}

/// Result of cache validation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValidationResult {
    /// Entry is fresh and valid.
    Fresh,
    /// Entry expired (TTL).
    Expired,
    /// Entry needs revalidation (ETag/git check).
    NeedsRevalidation,
    /// Entry not found.
    NotFound,
}

impl<'a> CacheValidator<'a> {
    /// Create a new cache validator.
    pub fn new(store: &'a CacheStore) -> Self {
        Self { store }
    }

    /// Validate a cache entry based on strategy.
    pub fn validate(
        &self,
        source_id: &str,
        template_name: &str,
        strategy: RemoteCacheStrategy,
    ) -> Result<ValidationResult> {
        let entry = match self.store.load(source_id, template_name)? {
            Some(e) => e,
            None => return Ok(ValidationResult::NotFound),
        };

        match strategy {
            RemoteCacheStrategy::Ttl => self.validate_ttl(&entry),
            RemoteCacheStrategy::Etag => self.validate_etag(&entry),
            RemoteCacheStrategy::Git => self.validate_git(&entry),
        }
    }

    /// Validate using TTL only.
    fn validate_ttl(&self, entry: &CacheEntry) -> Result<ValidationResult> {
        if entry.is_expired() {
            Ok(ValidationResult::Expired)
        } else {
            Ok(ValidationResult::Fresh)
        }
    }

    /// Validate with ETag strategy.
    ///
    /// If TTL expired, needs revalidation via HTTP.
    fn validate_etag(&self, entry: &CacheEntry) -> Result<ValidationResult> {
        if entry.is_expired() {
            if entry.metadata.etag.is_some() {
                Ok(ValidationResult::NeedsRevalidation)
            } else {
                Ok(ValidationResult::Expired)
            }
        } else {
            Ok(ValidationResult::Fresh)
        }
    }

    /// Validate with git strategy.
    ///
    /// If TTL expired, needs revalidation via git.
    fn validate_git(&self, entry: &CacheEntry) -> Result<ValidationResult> {
        if entry.is_expired() {
            if entry.metadata.commit_sha.is_some() {
                Ok(ValidationResult::NeedsRevalidation)
            } else {
                Ok(ValidationResult::Expired)
            }
        } else {
            Ok(ValidationResult::Fresh)
        }
    }

    /// Clean up expired entries (TTL-only cleanup).
    pub fn cleanup_expired(&self) -> Result<usize> {
        let entries = self.store.list()?;
        let mut removed = 0;

        for entry in entries {
            if entry.is_expired() && self.store.remove(&entry.source_id, &entry.template_name)? {
                removed += 1;
            }
        }

        Ok(removed)
    }

    /// Get entries older than a duration.
    pub fn entries_older_than(&self, age: Duration) -> Result<Vec<CacheEntry>> {
        let entries = self.store.list()?;
        let cutoff = Utc::now() - age;

        Ok(entries
            .into_iter()
            .filter(|e| e.metadata.cached_at < cutoff)
            .collect())
    }
}

/// Parse a TTL string like "7d", "24h", "30m".
pub fn parse_ttl(ttl: &str) -> Result<Duration> {
    let ttl = ttl.trim().to_lowercase();
    let parse_num = |s: &str| -> Result<i64> {
        s.parse().map_err(|e| BivvyError::CacheError {
            message: format!("Invalid TTL value '{}': {}", s, e),
        })
    };

    if let Some(days) = ttl.strip_suffix('d') {
        let n = parse_num(days)?;
        Ok(Duration::days(n))
    } else if let Some(hours) = ttl.strip_suffix('h') {
        let n = parse_num(hours)?;
        Ok(Duration::hours(n))
    } else if let Some(mins) = ttl.strip_suffix('m') {
        let n = parse_num(mins)?;
        Ok(Duration::minutes(n))
    } else if let Some(secs) = ttl.strip_suffix('s') {
        let n = parse_num(secs)?;
        Ok(Duration::seconds(n))
    } else {
        // Assume seconds if no suffix
        let n = parse_num(&ttl)?;
        Ok(Duration::seconds(n))
    }
}

/// Format a duration for display.
pub fn format_duration(duration: Duration) -> String {
    let secs = duration.num_seconds();

    if secs >= 86400 {
        let days = secs / 86400;
        format!("{}d", days)
    } else if secs >= 3600 {
        let hours = secs / 3600;
        format!("{}h", hours)
    } else if secs >= 60 {
        let mins = secs / 60;
        format!("{}m", mins)
    } else {
        format!("{}s", secs)
    }
}

