//! Shell reload resume state management.
//!
//! This module provides functionality for saving and restoring execution
//! state across shell reloads.

use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Mutex;

use crate::error::BivvyError;

type Result<T> = crate::error::Result<T>;

// Override path for testing
static STATE_PATH_OVERRIDE: Mutex<Option<PathBuf>> = Mutex::new(None);

/// State saved for resuming after shell reload.
///
/// # Example
///
/// ```no_run
/// use bivvy::shell::ResumeState;
/// use std::path::PathBuf;
///
/// // Create a resume state
/// let state = ResumeState {
///     project_root: PathBuf::from("/test/project"),
///     workflow: "default".to_string(),
///     completed_steps: vec!["step1".to_string()],
///     pending_step: "step2".to_string(),
///     timestamp: chrono::Utc::now(),
/// };
///
/// // Save state to disk
/// state.save().unwrap();
///
/// // Later, load state back
/// let loaded = ResumeState::load().unwrap().unwrap();
/// assert_eq!(loaded.workflow, "default");
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResumeState {
    /// Project root path.
    pub project_root: PathBuf,
    /// Workflow being executed.
    pub workflow: String,
    /// Steps that have been completed.
    pub completed_steps: Vec<String>,
    /// Step that triggered the reload.
    pub pending_step: String,
    /// Timestamp when reload was requested.
    pub timestamp: chrono::DateTime<chrono::Utc>,
}

impl ResumeState {
    /// Save resume state to disk.
    pub fn save(&self) -> Result<PathBuf> {
        let path = Self::state_path();
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let content = serde_json::to_string_pretty(self).map_err(|e| BivvyError::ShellError {
            message: format!("Failed to serialize resume state: {}", e),
        })?;
        std::fs::write(&path, content)?;
        Ok(path)
    }

    /// Load resume state if it exists.
    pub fn load() -> Result<Option<Self>> {
        let path = Self::state_path();
        if !path.exists() {
            return Ok(None);
        }
        let content = std::fs::read_to_string(&path)?;
        let state: Self =
            serde_json::from_str(&content).map_err(|e| BivvyError::ShellError {
                message: format!("Failed to deserialize resume state: {}", e),
            })?;
        Ok(Some(state))
    }

    /// Clear saved resume state.
    pub fn clear() -> Result<()> {
        let path = Self::state_path();
        if path.exists() {
            std::fs::remove_file(&path)?;
        }
        Ok(())
    }

    /// Check if there is a resume state available.
    pub fn exists() -> bool {
        Self::state_path().exists()
    }

    /// Get the resume state file path.
    fn state_path() -> PathBuf {
        if let Ok(guard) = STATE_PATH_OVERRIDE.lock() {
            if let Some(ref path) = *guard {
                return path.clone();
            }
        }
        crate::sys::data_local_dir()
            .unwrap_or_else(|| PathBuf::from("~/.local/share"))
            .join("bivvy")
            .join("resume-state.json")
    }

    /// Set the state path override (for testing).
    #[cfg(test)]
    pub fn set_state_path_override(path: Option<PathBuf>) {
        if let Ok(mut guard) = STATE_PATH_OVERRIDE.lock() {
            *guard = path;
        }
    }
}

/// Options for shell reload prompt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReloadChoice {
    /// Reload shell and continue automatically.
    ReloadAndContinue,
    /// Exit and let user reload manually.
    ExitManual,
    /// Skip the step requiring reload.
    Skip,
}

impl ReloadChoice {
    /// Get the human-readable description for this choice.
    pub fn description(&self) -> &'static str {
        match self {
            Self::ReloadAndContinue => "Reload shell and continue (recommended)",
            Self::ExitManual => "Exit and reload manually",
            Self::Skip => "Skip this step",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;
    use tempfile::TempDir;

    // Mutex to serialize tests that use state path override
    static TEST_MUTEX: Mutex<()> = Mutex::new(());

    fn with_temp_state<F, R>(f: F) -> R
    where
        F: FnOnce() -> R,
    {
        let _guard = TEST_MUTEX.lock().unwrap();
        let temp = TempDir::new().unwrap();
        let state_path = temp.path().join("resume-state.json");
        ResumeState::set_state_path_override(Some(state_path));
        let result = f();
        ResumeState::set_state_path_override(None);
        result
    }

    #[test]
    fn saves_and_loads_resume_state() {
        with_temp_state(|| {
            let state = ResumeState {
                project_root: PathBuf::from("/test/project"),
                workflow: "default".to_string(),
                completed_steps: vec!["step1".to_string()],
                pending_step: "step2".to_string(),
                timestamp: chrono::Utc::now(),
            };

            state.save().unwrap();
            let loaded = ResumeState::load().unwrap().unwrap();

            assert_eq!(loaded.workflow, "default");
            assert_eq!(loaded.completed_steps.len(), 1);
            assert_eq!(loaded.pending_step, "step2");
        });
    }

    #[test]
    fn clear_removes_state() {
        with_temp_state(|| {
            let state = ResumeState {
                project_root: PathBuf::from("/test"),
                workflow: "default".to_string(),
                completed_steps: vec![],
                pending_step: "step1".to_string(),
                timestamp: chrono::Utc::now(),
            };

            state.save().unwrap();
            assert!(ResumeState::exists());

            ResumeState::clear().unwrap();
            assert!(!ResumeState::exists());
            assert!(ResumeState::load().unwrap().is_none());
        });
    }

    #[test]
    fn load_returns_none_when_no_state() {
        with_temp_state(|| {
            let loaded = ResumeState::load().unwrap();
            assert!(loaded.is_none());
        });
    }

    #[test]
    fn exists_returns_false_when_no_state() {
        with_temp_state(|| {
            assert!(!ResumeState::exists());
        });
    }

    #[test]
    fn reload_choice_descriptions() {
        assert!(ReloadChoice::ReloadAndContinue
            .description()
            .contains("Reload"));
        assert!(ReloadChoice::ExitManual.description().contains("Exit"));
        assert!(ReloadChoice::Skip.description().contains("Skip"));
    }
}

//! Remote template loading from HTTP and Git sources.
//!
//! Fetches templates from URLs defined in `template_sources` and caches
//! them using the shared cache infrastructure (HTTP) or the on-disk clone
//! directory (Git).

use std::collections::HashMap;
use std::fs;
use std::path::Path;

use super::fetch::{GitFetcher, HttpFetcher};
use super::template::Template;
use crate::cache::{parse_ttl, CacheStore};
use crate::config::schema::{TemplateSource as TemplateSourceConfig, TemplateSourceKind};
use crate::error::BivvyError;

type Result<T> = crate::error::Result<T>;

/// Loads templates from remote sources with caching.
#[derive(Debug, Clone)]
pub struct RemoteLoader {
    /// Fetched and parsed templates, keyed by `category/name`.
    templates: HashMap<String, (Template, u32)>,
}

impl RemoteLoader {
    /// Create a new remote loader by fetching templates from the given sources.
    ///
    /// HTTP sources are fetched into the shared `CacheStore`; Git sources are
    /// cloned (or updated) into `git_fetcher`'s clone directory and their
    /// templates directory is walked for `*.yml`/`*.yaml` files.
    pub fn new(
        sources: &[TemplateSourceConfig],
        http_fetcher: &HttpFetcher,
        git_fetcher: &GitFetcher,
        cache: &CacheStore,
    ) -> Result<Self> {
        let mut templates = HashMap::new();

        // Visit sources in priority order (lower `priority` number wins on
        // collision). Stable sort preserves declaration order among ties so
        // the user's listed-first source breaks the tie.
        let mut ordered: Vec<&TemplateSourceConfig> = sources.iter().collect();
        ordered.sort_by_key(|s| s.priority);

        for source in ordered {
            let result = match source.effective_kind() {
                TemplateSourceKind::Http => Self::load_http_source(source, http_fetcher, cache),
                TemplateSourceKind::Git => Self::load_git_source(source, git_fetcher),
            };

            match result {
                Ok(loaded) => {
                    for template in loaded {
                        // Higher-priority sources (lower number) win on collision.
                        let key = format!("{}/{}", template.category, template.name);
                        templates.entry(key).or_insert((template, source.priority));
                    }
                }
                Err(e) => {
                    tracing::warn!("Failed to load templates from {}: {}", source.url, e);
                }
            }
        }

        Ok(Self { templates })
    }

    /// Create an empty remote loader (no sources).
    pub fn empty() -> Self {
        Self {
            templates: HashMap::new(),
        }
    }

    /// Load templates from a single HTTP source.
    fn load_http_source(
        source: &TemplateSourceConfig,
        fetcher: &HttpFetcher,
        cache: &CacheStore,
    ) -> Result<Vec<Template>> {
        let source_id = format!("http:{}", source.url);

        // Check cache first
        if let Some(entry) = cache.load(&source_id, "_index")? {
            if !entry.is_expired() {
                let content = cache.read_content(&entry)?;
                return Self::parse_templates(&content);
            }
        }

        // Fetch from remote
        let response = fetcher.fetch(&source.url).map_err(|e| BivvyError::RegistryError {
            message: format!("Failed to fetch template source {}: {}", source.url, e),
        })?;

        // Cache the response
        let ttl_seconds = source
            .cache
            .as_ref()
            .and_then(|c| parse_ttl(&c.ttl).ok())
            .map(|d| d.num_seconds() as u64)
            .unwrap_or(604800);
        cache.store(&source_id, "_index", &response.content, ttl_seconds)?;

        Self::parse_templates(&response.content)
    }

    /// Load templates from a single Git source.
    ///
    /// Clones (or updates) the repository, then walks `source.path` (or the
    /// repository root if `path` is unset) for `*.yml`/`*.yaml` files. Each
    /// file is parsed as a [`Template`]. Files that fail to parse are
    /// reported via `tracing::warn!` and skipped.
    ///
    /// URL scheme validation is the caller's responsibility: production code
    /// goes through [`Registry::with_remote_sources`](crate::registry::Registry::with_remote_sources),
    /// which validates each source up front.
    fn load_git_source(
        source: &TemplateSourceConfig,
        fetcher: &GitFetcher,
    ) -> Result<Vec<Template>> {
        let result = fetcher
            .fetch_unchecked(&source.url, source.git_ref.as_deref())
            .map_err(|e| BivvyError::RegistryError {
                message: format!("Failed to clone git source {}: {}", source.url, e),
            })?;

        let walk_root = match &source.path {
            Some(sub) => result.local_path.join(sub),
            None => result.local_path.clone(),
        };

        if !walk_root.exists() {
            return Err(BivvyError::RegistryError {
                message: format!(
                    "Git source path does not exist: {} (in {})",
                    source.path.as_deref().unwrap_or(""),
                    source.url
                ),
            });
        }

        let mut templates = Vec::new();
        Self::walk_templates(&walk_root, &mut templates);
        Ok(templates)
    }

    /// Recursively walk `dir` collecting templates from `*.yml` / `*.yaml` files.
    /// Parse failures are logged and skipped so a single bad file does not
    /// abort the whole source.
    fn walk_templates(dir: &Path, out: &mut Vec<Template>) {
        let Ok(entries) = fs::read_dir(dir) else {
            return;
        };

        for entry in entries.flatten() {
            let path = entry.path();

            // Skip the .git directory and any other dotfiles.
            if path
                .file_name()
                .and_then(|n| n.to_str())
                .map(|n| n.starts_with('.'))
                .unwrap_or(false)
            {
                continue;
            }

            if path.is_dir() {
                Self::walk_templates(&path, out);
                continue;
            }

            let is_yaml = path
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| e == "yml" || e == "yaml")
                .unwrap_or(false);
            if !is_yaml {
                continue;
            }

            match fs::read_to_string(&path) {
                Ok(content) => match Self::parse_templates(&content) {
                    Ok(parsed) => out.extend(parsed),
                    Err(e) => {
                        tracing::warn!("Failed to parse template at {}: {}", path.display(), e);
                    }
                },
                Err(e) => {
                    tracing::warn!("Failed to read template at {}: {}", path.display(), e);
                }
            }
        }
    }

    /// Parse a YAML string containing one or more templates.
    ///
    /// Supports two formats:
    /// 1. A single template YAML document
    /// 2. A YAML array of templates
    fn parse_templates(content: &str) -> Result<Vec<Template>> {
        // Try parsing as a list first
        if let Ok(templates) = serde_yaml::from_str::<Vec<Template>>(content) {
            return Ok(templates);
        }

        // Try as a single template
        if let Ok(template) = serde_yaml::from_str::<Template>(content) {
            return Ok(vec![template]);
        }

        Err(BivvyError::RegistryError {
            message: "Remote source returned content that is neither a template nor a list of templates".to_string(),
        })
    }

    /// Get a template by name (unqualified -- returns first match).
    pub fn get(&self, name: &str) -> Option<&Template> {
        if let Some((t, _)) = self.templates.get(name) {
            return Some(t);
        }
        self.templates
            .values()
            .find(|(t, _)| t.name == name)
            .map(|(t, _)| t)
    }

    /// Get a template with its priority (unqualified -- returns first match).
    pub fn get_with_priority(&self, name: &str) -> Option<(&Template, u32)> {
        if let Some((t, p)) = self.templates.get(name) {
            return Some((t, *p));
        }
        self.templates
            .values()
            .find(|(t, _)| t.name == name)
            .map(|(t, p)| (t, *p))
    }

    /// Get a template with its priority, filtering by category.
    pub fn get_with_priority_by_category(
        &self,
        name: &str,
        category: &str,
    ) -> Option<(&Template, u32)> {
        let key = format!("{}/{}", category, name);
        self.templates.get(&key).map(|(t, p)| (t, *p))
    }

    /// Check if a template exists (by unqualified name).
    pub fn has(&self, name: &str) -> bool {
        self.templates.contains_key(name) || self.templates.values().any(|(t, _)| t.name == name)
    }

    /// Get all template names (qualified as `category/name`).
    pub fn template_names(&self) -> Vec<&str> {
        self.templates.keys().map(|s| s.as_str()).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::registry::fetch::git::create_bare_repo_with_templates;
    use crate::registry::fetch::HttpFetcher;
    use std::sync::Mutex;
    use tempfile::TempDir;

    // Serialize git-process tests to avoid flaky failures under parallel execution.
    static GIT_LOCK: Mutex<()> = Mutex::new(());

    #[test]
    fn empty_loader_has_no_templates() {
        let loader = RemoteLoader::empty();
        assert!(!loader.has("anything"));
        assert!(loader.template_names().is_empty());
    }

    #[test]
    fn parse_single_template() {
        let yaml = r#"
name: remote-tool
description: "A remote tool"
category: tools
step:
  command: echo hello
"#;

        let templates = RemoteLoader::parse_templates(yaml).unwrap();
        assert_eq!(templates.len(), 1);
        assert_eq!(templates[0].name, "remote-tool");
    }

    #[test]
    fn parse_template_list() {
        let yaml = r#"
- name: tool-a
  description: "Tool A"
  category: tools
  step:
    command: echo a
- name: tool-b
  description: "Tool B"
  category: tools
  step:
    command: echo b
"#;

        let templates = RemoteLoader::parse_templates(yaml).unwrap();
        assert_eq!(templates.len(), 2);
        assert_eq!(templates[0].name, "tool-a");
        assert_eq!(templates[1].name, "tool-b");
    }

    #[test]
    fn parse_invalid_content_returns_error() {
        let result = RemoteLoader::parse_templates("not a template at all: [[[");
        assert!(result.is_err());
    }

    fn make_source(url: String, kind: TemplateSourceKind) -> TemplateSourceConfig {
        TemplateSourceConfig {
            kind: Some(kind),
            url,
            git_ref: Some("main".to_string()),
            path: None,
            priority: 50,
            timeout: 30,
            cache: None,
            auth: None,
        }
    }

    #[test]
    fn loads_templates_from_git_source_root() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();

        let template_yaml = r#"
name: git-tool
description: "Tool from a git remote"
category: tools
step:
  command: git-tool run
"#;
        let bare = create_bare_repo_with_templates(temp.path(), &[("git-tool.yml", template_yaml)]);

        let cache = CacheStore::new(temp.path().join("cache"));
        let http = HttpFetcher::new();
        let git = GitFetcher::new(temp.path().join("clones"));

        let sources = vec![make_source(
            bare.to_string_lossy().to_string(),
            TemplateSourceKind::Git,
        )];

        let loader = RemoteLoader::new(&sources, &http, &git, &cache).unwrap();
        let template = loader
            .get("git-tool")
            .expect("git-tool template should be loaded from the git source");
        assert_eq!(template.name, "git-tool");
        assert_eq!(template.description, "Tool from a git remote");
    }

    #[test]
    fn git_source_loads_only_from_configured_subdir() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();

        let included_yaml = r#"
name: included-tool
description: "Included via path"
category: tools
step:
  command: included
"#;
        let excluded_yaml = r#"
name: excluded-tool
description: "Outside the configured path"
category: tools
step:
  command: excluded
"#;
        let bare = create_bare_repo_with_templates(
            temp.path(),
            &[
                ("templates/included-tool.yml", included_yaml),
                ("docs/excluded-tool.yml", excluded_yaml),
            ],
        );

        let cache = CacheStore::new(temp.path().join("cache"));
        let http = HttpFetcher::new();
        let git = GitFetcher::new(temp.path().join("clones"));

        let mut source = make_source(bare.to_string_lossy().to_string(), TemplateSourceKind::Git);
        source.path = Some("templates".to_string());

        let loader = RemoteLoader::new(&[source], &http, &git, &cache).unwrap();
        assert!(
            loader.has("included-tool"),
            "included-tool should be loaded from the configured subdir"
        );
        assert!(
            !loader.has("excluded-tool"),
            "excluded-tool is outside the path filter and should not be loaded"
        );
    }

    #[test]
    fn git_source_recursively_walks_subdirectories() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();

        let nested_yaml = r#"
name: nested-tool
description: "Nested under a category dir"
category: build
step:
  command: nested
"#;
        let bare = create_bare_repo_with_templates(
            temp.path(),
            &[("steps/build/nested-tool.yml", nested_yaml)],
        );

        let cache = CacheStore::new(temp.path().join("cache"));
        let http = HttpFetcher::new();
        let git = GitFetcher::new(temp.path().join("clones"));

        let source = make_source(bare.to_string_lossy().to_string(), TemplateSourceKind::Git);

        let loader = RemoteLoader::new(&[source], &http, &git, &cache).unwrap();
        assert!(
            loader.has("nested-tool"),
            "templates in nested subdirectories should be discovered"
        );
    }

    #[test]
    fn git_source_skips_unparseable_yaml() {
        let _lock = GIT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let temp = TempDir::new().unwrap();

        let valid_yaml = r#"
name: ok-tool
description: "Parses cleanly"
category: tools
step:
  command: ok
"#;
        let invalid_yaml = "this: is: not: valid: template: yaml: [";
        let bare = create_bare_repo_with_templates(
            temp.path(),
            &[("ok-tool.yml", valid_yaml), ("broken.yml", invalid_yaml)],
        );

        let cache = CacheStore::new(temp.path().join("cache"));
        let http = HttpFetcher::new();
        let git = GitFetcher::new(temp.path().join("clones"));

        let sources = vec![make_source(
            bare.to_string_lossy().to_string(),
            TemplateSourceKind::Git,
        )];

        let loader = RemoteLoader::new(&sources, &http, &git, &cache).unwrap();
        assert!(
            loader.has("ok-tool"),
            "valid template should still be loaded even if a sibling fails to parse"
        );
    }
}

//! Session wrapper for CLI commands.
//!
//! This module provides session tracking integration for CLI command execution.

use crate::session::{default_store_path, Session, SessionId, SessionMetadata, SessionStore};

type Result<T> = crate::error::Result<T>;

/// Wraps command execution with session tracking.
pub struct SessionWrapper {
    store: SessionStore,
    current_id: SessionId,
    metadata: SessionMetadata,
    stdout_buffer: Vec<u8>,
    stderr_buffer: Vec<u8>,
}

impl SessionWrapper {
    /// Create a new session wrapper.
    pub fn new(command: &str, args: Vec<String>) -> Self {
        Self {
            store: SessionStore::new(default_store_path()),
            current_id: SessionId::new(),
            metadata: SessionMetadata::new(command, args),
            stdout_buffer: Vec::new(),
            stderr_buffer: Vec::new(),
        }
    }

    /// Get the current session ID.
    pub fn session_id(&self) -> &SessionId {
        &self.current_id
    }

    /// Get mutable access to metadata for adding context.
    pub fn metadata_mut(&mut self) -> &mut SessionMetadata {
        &mut self.metadata
    }

    /// Capture stdout.
    pub fn capture_stdout(&mut self, s: &str) {
        self.stdout_buffer.extend_from_slice(s.as_bytes());
    }

    /// Capture stderr.
    pub fn capture_stderr(&mut self, s: &str) {
        self.stderr_buffer.extend_from_slice(s.as_bytes());
    }

    /// Finalize and save the session.
    pub fn finalize(mut self, exit_code: i32) -> Result<SessionId> {
        let stdout = String::from_utf8_lossy(&self.stdout_buffer).to_string();
        let stderr = String::from_utf8_lossy(&self.stderr_buffer).to_string();

        self.metadata.finalize(exit_code, stdout, stderr);

        let session = Session {
            id: self.current_id.clone(),
            metadata: self.metadata,
        };

        self.store.save(&session)?;

        // Cleanup old sessions (keep last 100)
        let _ = self.store.cleanup(100);

        Ok(self.current_id)
    }

    /// Get the latest session ID (for feedback command).
    pub fn get_latest_session_id() -> Result<Option<SessionId>> {
        let store = Self::get_store();
        Ok(store.get_latest()?.map(|s| s.id))
    }

    /// Get the session store for reading sessions.
    pub fn get_store() -> SessionStore {
        SessionStore::new(default_store_path())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    // Use a custom store for testing to avoid polluting the real store
    fn create_test_wrapper(
        command: &str,
        args: Vec<String>,
        store_path: std::path::PathBuf,
    ) -> SessionWrapper {
        SessionWrapper {
            store: SessionStore::new(store_path),
            current_id: SessionId::new(),
            metadata: SessionMetadata::new(command, args),
            stdout_buffer: Vec::new(),
            stderr_buffer: Vec::new(),
        }
    }

    #[test]
    fn session_wrapper_creation() {
        let wrapper = SessionWrapper::new("run", vec!["--verbose".to_string()]);
        assert!(wrapper.session_id().as_str().starts_with("sess_"));
    }

    #[test]
    fn session_wrapper_capture_output() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("list", vec![], temp.path().join("sessions"));

        wrapper.capture_stdout("Hello\n");
        wrapper.capture_stdout("World\n");
        wrapper.capture_stderr("Warning: something\n");

        let id = wrapper.finalize(0).unwrap();

        // Verify the session was saved
        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert!(session.metadata.stdout.contains("Hello"));
        assert!(session.metadata.stdout.contains("World"));
        assert!(session.metadata.stderr.contains("Warning"));
    }

    #[test]
    fn session_wrapper_metadata_modification() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));

        wrapper.metadata_mut().set_flag("verbose", true);
        wrapper.metadata_mut().context.workflow = Some("default".to_string());

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(
            session.metadata.flags.get("verbose"),
            Some(&serde_json::json!(true))
        );
        assert_eq!(
            session.metadata.context.workflow,
            Some("default".to_string())
        );
    }

    #[test]
    fn session_wrapper_finalize_exit_code() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));

        let id = wrapper.finalize(1).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(session.metadata.exit_code, Some(1));
    }

    #[test]
    fn session_wrapper_cleanup_old_sessions() {
        let temp = TempDir::new().unwrap();
        let store_path = temp.path().join("sessions");

        // Create 105 sessions
        for i in 0..105 {
            let wrapper = create_test_wrapper(&format!("cmd{}", i), vec![], store_path.clone());
            wrapper.finalize(0).unwrap();
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        let store = SessionStore::new(&store_path);
        let sessions = store.list_recent(usize::MAX).unwrap();

        // Should have at most 100 sessions due to cleanup
        assert!(sessions.len() <= 100);
    }

    #[test]
    fn session_wrapper_get_store() {
        // Test that get_store returns a valid store
        let store = SessionWrapper::get_store();
        // Just check the path is set correctly
        assert!(store.path().ends_with("sessions"));
    }

    #[test]
    fn session_wrapper_get_latest_session_id_empty_store() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let latest = store.get_latest().unwrap();
        assert!(latest.is_none());
    }

    #[test]
    fn session_wrapper_get_latest_session_id_returns_most_recent() {
        let temp = TempDir::new().unwrap();
        let store_path = temp.path().join("sessions");

        // Create two sessions with a small delay so timestamps differ
        let first = create_test_wrapper("first", vec![], store_path.clone());
        let _first_id = first.finalize(0).unwrap();
        std::thread::sleep(std::time::Duration::from_millis(2));

        let second = create_test_wrapper("second", vec![], store_path.clone());
        let second_id = second.finalize(0).unwrap();

        let store = SessionStore::new(&store_path);
        let latest = store.get_latest().unwrap().expect("should have a session");
        assert_eq!(latest.id, second_id);
        assert_eq!(latest.metadata.command, "second");
    }

    #[test]
    fn session_wrapper_capture_multiple_calls() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("test", vec![], temp.path().join("sessions"));

        // Multiple capture calls
        wrapper.capture_stdout("line1\n");
        wrapper.capture_stdout("line2\n");
        wrapper.capture_stdout("line3\n");
        wrapper.capture_stderr("err1\n");
        wrapper.capture_stderr("err2\n");

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert!(session.metadata.stdout.contains("line1"));
        assert!(session.metadata.stdout.contains("line2"));
        assert!(session.metadata.stdout.contains("line3"));
        assert!(session.metadata.stderr.contains("err1"));
        assert!(session.metadata.stderr.contains("err2"));
    }

    #[test]
    fn session_wrapper_session_id_accessor() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper("cmd", vec![], temp.path().join("sessions"));

        let id = wrapper.session_id();
        assert!(id.as_str().starts_with("sess_"));
    }

    #[test]
    fn session_wrapper_with_args() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper(
            "run",
            vec!["--verbose".to_string(), "--force".to_string()],
            temp.path().join("sessions"),
        );

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(session.metadata.command, "run");
        assert_eq!(session.metadata.args, vec!["--verbose", "--force"]);
    }
}

