        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let id = SessionId::new();
        let mut meta = SessionMetadata::new("list", vec![]);
        meta.finalize(0, "output".to_string(), String::new());

        let session = Session {
